        juz: 17,
        page: 333,
        arab: "\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0622\u062a\u0650\u064a\u064e\u0629\u064c \u0644\u0651\u064e\u0627 \u0631\u064e\u064a\u0652\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0628\u064f\u0648\u0631\u0650",
        transliteration: "Wa annas Saa'ata aatiya tul laa raiba feeha wa annal laaha yab'asuman fil quboor",
        translation: "Dan sungguh, (hari) Kiamat itu pasti datang, tidak ada keraguan padanya; dan sungguh, Allah akan membangkitkan siapa pun yang di dalam kubur.",
        shortTafsir: "Dan ketahuilah, wahai manusia, sesungguhnya hari Kiamat itu pasti datang, meskipun Allah merahasiakan waktunya. Oleh karena itu, tidak ada keraguan padanya, karena Kiamat itu ketetapan Allah; dan sungguh, pada hari Kiamat itu Allah akan membangkitkan semua yang berada di dalam kubur untuk dikumpulkan di Mahsyar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2602",
      ),
      Ayah(
        numberInSurah: 8,
        numberInQuran: 2603,
        juz: 17,
        page: 333,
        arab: "\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0639\u0650\u0644\u0652\u0645\u064d \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u0651\u064f\u0646\u0650\u064a\u0631\u064d",
        transliteration: "Wa minan naasi mai yujaadilu fil laahi bighairi 'ilminw wa laa hudanw wa laa Kitaabim Muneer",
        translation: "Dan di antara manusia ada yang berbantahan tentang Allah tanpa ilmu, tanpa petunjuk dan tanpa kitab (wahyu) yang memberi penerangan.",
        shortTafsir: "Manusia ada yang bertindak melampaui batas. Allah menegaskan, bahwa\u00a0di antara manusia ada yang berbantah tentang Allah,\u00a0mengingkari agama-Nya, tidak meyakini kehidupan sesudah mati, dan tidak meyakini adanya akhirat\u00a0tanpa ilmu\u00a0yang benar dan meyakinkan, juga\u00a0tanpa petunjuk\u00a0dari Allah, dan\u00a0tanpa\u00a0sumber dari\u00a0kitab\u00a0wahyu yang disampaikan kepada para rasul\u00a0yang memberi penerangan\u00a0dari kegelapan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2603",
      ),
      Ayah(
        numberInSurah: 9,
        numberInQuran: 2604,
        juz: 17,
        page: 333,
        arab: "\u062b\u064e\u0627\u0646\u0650\u064a\u064e \u0639\u0650\u0637\u0652\u0641\u0650\u0647\u0650 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06d6 \u0644\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062e\u0650\u0632\u0652\u064a\u064c \u06d6 \u0648\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064f\u0647\u064f \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",
        transliteration: "Saaniya 'itfihee liyudilla 'an sabeelil laahi lahoo fiddun yaa khizyunw wa nuzeequhoo Yawmal Qiyaamati 'azaabal lhareeq",
        translation: "Sambil memalingkan lambungnya (dengan congkak) untuk menyesatkan manusia dari jalan Allah. Dia mendapat kehinaan di dunia, dan pada hari Kiamat Kami berikan kepadanya rasa azab neraka yang membakar.",
        shortTafsir: "Manusia yang mengingkari Allah dengan hatinya yang gelap, sambil memalingkan lambungnya dengan congkak berusaha dengan segala cara untuk menyesatkan manusia dari jalan Allah. Dia sebenarnya mendapat kehinaan di dunia karena hidup tanpa kecerdasan emosi dan kecerdasan spiritual hingga hidupnya dibiarkan tanpa bimbingan Allah; dan pada hari Kiamat sebagai balasan atas kekufurannya, Kami berikan kepadanya rasa azab neraka yang membakar hingga kulitnya hangus, kemudian kulitnya diperbarui supaya terus bisa merasakan azab yang membakar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2604",
      ),
      Ayah(
        numberInSurah: 10,
        numberInQuran: 2605,
        juz: 17,
        page: 333,
        arab: "\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u064a\u064e\u062f\u064e\u0627\u0643\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u064a\u0652\u0633\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0627\u0645\u064d \u0644\u0651\u0650\u0644\u0652\u0639\u064e\u0628\u0650\u064a\u062f\u0650",
        transliteration: "Zaalika bimaa qaddamat yadaaka wa annal laaha laisa bizallaamil lil'abeed",
        translation: "(Akan dikatakan kepadanya), \u201cItu karena perbuatan yang dilakukan dahulu oleh kedua tanganmu, dan Allah sekali-kali tidak menzalimi hamba-hamba-Nya.",
        shortTafsir: "Pada hari Kiamat akan dikatakan kepada orang kafir, \u201cHukuman\u00a0itu\u00a0diberikan kepada kamu,\u00a0karena perbuatan yang dilakukan dahulu oleh kedua tanganmu, menolak agama Allah dan berusaha menyesatkan manusia dari jalan Allah,\u00a0dan Allah sekali-kali tidak menzalimi hamba-hamba-Nya\u00a0dengan menghukum mereka yang tidak bersalah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2605",
      ),
      Ayah(
        numberInSurah: 11,
        numberInQuran: 2606,
        juz: 17,
        page: 333,
        arab: "\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u0652\u0641\u064d \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0627\u0637\u0652\u0645\u064e\u0623\u064e\u0646\u0651\u064e \u0628\u0650\u0647\u0650 \u06d6 \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u0652\u0647\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064c \u0627\u0646\u0642\u064e\u0644\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u0652\u0647\u0650\u0647\u0650 \u062e\u064e\u0633\u0650\u0631\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062e\u064f\u0633\u0652\u0631\u064e\u0627\u0646\u064f \u0627\u0644\u0652\u0645\u064f\u0628\u0650\u064a\u0646\u064f",
        transliteration: "Wa minan naasi mai ya'budul laaha 'alaa harfin fa in asaabahoo khairunit maanna bihee wa in asaabat hu fitnatunin qalaba 'alaa wajhihee khasirad dunyaa wal aakhirah; zaalika huwal khusraanul mubeen",
        translation: "Dan di antara manusia ada yang menyembah Allah hanya di tepi; maka jika dia memperoleh kebajikan, dia merasa puas, dan jika dia ditimpa suatu cobaan, dia berbalik ke belakang. Dia rugi di dunia dan di akhirat. Itulah kerugian yang nyata.",
        shortTafsir: "Di antara umat Islam, ada yang beragama secara total, tetapi ada pula yang beragama di pinggirannya saja. Dan di antara manusia ada yang menyembah Allah hanya di tepi, karena rasa beragamanya tidak meresap ke dalam hati dan tidak mengakar ke dalam jiwa. Maka jika dia memperoleh kebajikan duniawi karena keislamannya, dia merasa puas, dan sebaliknya jika dia ditimpa suatu cobaan, baik dirinya maupun keluarganya, dia segera berbalik ke belakang, kembali kepada agama lama. Dia menjadi orang murtad, sehingga mendapat ke-rugi-an di dunia, karena dinilai tidak punya pendirian dan\u00a0kerugian di akhirat, karena kekal di dalam neraka. Kerugian di akhirat itulah kerugian yang nyata.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2606",
      ),
      Ayah(
        numberInSurah: 12,
        numberInQuran: 2607,
        juz: 17,
        page: 333,
        arab: "\u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f \u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064f \u0627\u0644\u0652\u0628\u064e\u0639\u0650\u064a\u062f\u064f",
        transliteration: "Yad'oo min doonil laahi maa laa yadurruhoo wa maa laa yanfa'uh' zaalika huwad dalaalul ba'ed",
        translation: "Dia menyeru kepada selain Allah sesuatu yang tidak dapat mendatangkan bencana dan tidak (pula) memberi manfaat kepadanya. Itulah kesesatan yang jauh.",
        shortTafsir: "Dia, orang-orang yang murtad kembali\u00a0menyeru kepada selain Allah, baik benda, manusia, roh leluhur, jin maupun setan, yang semuanya merupakan\u00a0sesuatu yang tidak dapat mendatangkan bencana, baik bagi dirinya maupun lingkungan sosialnya,\u00a0dan tidak\u00a0pula semua yang disembah itu\u00a0memberi manfaat kepadanya.\u00a0Mengambil kekufuran dan melepaskan iman dengan murtad\u00a0itulah kesesatan yang jauh\u00a0dari kebenaran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2607",
      ),
      Ayah(
        numberInSurah: 13,
        numberInQuran: 2608,
        juz: 17,
        page: 333,
        arab: "\u064a\u064e\u062f\u0652\u0639\u064f\u0648 \u0644\u064e\u0645\u064e\u0646 \u0636\u064e\u0631\u0651\u064f\u0647\u064f \u0623\u064e\u0642\u0652\u0631\u064e\u0628\u064f \u0645\u0650\u0646 \u0646\u0651\u064e\u0641\u0652\u0639\u0650\u0647\u0650 \u06da \u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0639\u064e\u0634\u0650\u064a\u0631\u064f",
        transliteration: "Yad'oo laman darruhooo aqrabu min naf'ih; labi'salmawlaa wa labi'sal 'asheer",
        translation: "Dia menyeru kepada sesuatu yang (sebenarnya) bencananya lebih dekat daripada manfaatnya. Sungguh, itu seburuk-buruk penolong dan sejahat-jahat kawan.",
        shortTafsir: "Dia, orang kafir dan orang murtad itu, menyeru dalam ritual dan doanya kepada suatu sembahan yang sebenarnya bencananya dalam persembahan itu, lebih dekat daripada manfaatnya. Sungguh, jika mereka menyadari bahwa sembahan selain Allah itu adalah seburuk-buruk penolong karena menolong kepada kebinasaan, dan sejahat-jahat kawan karena berkawan dengan yang mencelakakan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2608",
      ),
      Ayah(
        numberInSurah: 14,
        numberInQuran: 2609,
        juz: 17,
        page: 333,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",
        transliteration: "Innal laaha yudkhilul laeena aamanoo wa 'amilus saalihaati jannaatin tajree min tahtihal anhaar; innal laaha yaf'alu maa yureed",
        translation: "(Sungguh,) Allah akan memasukkan orang-orang yang beriman dan mengerjakan kebajikan ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. Sungguh, Allah berbuat apa yang Dia kehendaki.",
        shortTafsir: "Berbeda dengan perlakuan Allah terhadap orang kafir dan murtad di atas,\u00a0sungguh, Allah akan memasukkan orang-orang yang beriman\u00a0yang menjaga imannya hingga akhir hayat\u00a0dan mengerjakan kebajikan\u00a0dengan ikhlas\u00a0ke dalam surga-surga yang mengalir di bawahnya sungai-sungai\u00a0sebagai kenikmatan yang tiada terhingga.\u00a0Sungguh, Allah berbuat apa yang Dia kehendaki\u00a0kepada hamba-hamba-Nya dengan adil.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2609",
      ),
      Ayah(
        numberInSurah: 15,
        numberInQuran: 2610,
        juz: 17,
        page: 333,
        arab: "\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u0645\u0652\u062f\u064f\u062f\u0652 \u0628\u0650\u0633\u064e\u0628\u064e\u0628\u064d \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u0652\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u0652 \u0641\u064e\u0644\u0652\u064a\u064e\u0646\u0638\u064f\u0631\u0652 \u0647\u064e\u0644\u0652 \u064a\u064f\u0630\u0652\u0647\u0650\u0628\u064e\u0646\u0651\u064e \u0643\u064e\u064a\u0652\u062f\u064f\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u063a\u0650\u064a\u0638\u064f",
        transliteration: "Man kaana yazunnu allai yansurahul laahu fid dunyaa wal aakhirati fal yamdud bisababin ilas samaaa'i summal yaqta' falyanzur hal yuzhibanna kaiduhoo maa yagheez",
        translation: "Barangsiapa menyangka bahwa Allah tidak akan menolongnya (Muhammad) di dunia dan di akhirat, maka hendaklah dia merentangkan tali ke langit-langit, ) lalu menggantung (diri), kemudian pikirkanlah apakah tipu dayanya itu dapat melenyapkan apa yang menyakitkan hatinya.",
        shortTafsir: "Pada ayat di atas Allah menerangkan sikap orang murtad dan hu-kuman atas mereka, serta balasan bagi orang beriman. Pada ayat ini Allah mempersilakan orang kafir yang tidak menyukai perkembangan Islam untuk menghentikan pertolongan-Nya. Barang siapa menyangka atau berpendapat bahwa Allah tidak akan menolongnya, Muhammad, di dunia dengan memperoleh kebebasan dari tekanan mereka di Mekah serta menemukan tempat yang tepat untuk menyebarkan Islam di Madinah, dan mendapat balasan kebaikan di akhirat, maka hendaklah dia merentangkan tali ke langit, lalu menggantung dirinya di langit, kemudian dari ketinggian itu berusahalah menghentikan pertolongan Allah kepada Rasul-Nya. Kemudian, lalu pikirkanlah apakah langkah tersebut dapat melenyapkan apa yang menyakitkan hatinya, pesatnya perkembangan Islam atas pertolongan Allah kepada kaum muslim.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2610",
      ),
      Ayah(
        numberInSurah: 16,
        numberInQuran: 2611,
        juz: 17,
        page: 334,
        arab: "\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u064d \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",
        transliteration: "Wa kazaalika anzalnaahu aayaatim baiyinaatinw wa annal laaha yahdee mai yureed",
        translation: "Dan demikianlah Kami telah menurunkannya (Al-Qur'an) yang merupakan ayat-ayat yang nyata; sesungguhnya Allah memberikan petunjuk kepada siapa yang Dia kehendaki.",
        shortTafsir: "Dan demikianlah Kami telah menurunkannya, Al-Qur\u2019an, kepada Nabi Muhammad, meskipun orang-orang kafir tidak menyukainya, sebab Al-Qur\u2019an itu\u00a0yang merupakan ayat-ayat yang nyata,\u00a0mudah dipahami, masuk akal, dan menyentuh hati bagi orang yang akal dan hatinya terbuka.\u00a0Sesungguhnya Allah memberikan petunjuk dengan memudahkan memahami Al-Qur\u2019an\u00a0kepada siapa\u00a0saja di antara umat manusia\u00a0yang Dia kehendaki.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2611",
      ),
      Ayah(
        numberInSurah: 17,
        numberInQuran: 2612,
        juz: 17,
        page: 334,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0626\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u062c\u064f\u0648\u0633\u064e \u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u0652\u0631\u064e\u0643\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064c",
        transliteration: "Innal lazeena aamanoo wallazeena haadoo was saabi'eena wan nasaaraa wal Majoosa wallazeena ashrakooo innal laaha yafsilu bainahum yawmal qiyaamah; innal laaha 'alaa kulli shai'in shaheed",
        translation: "Sesungguhnya orang-orang beriman, orang Yahudi, orang Sabiin, orang Nasrani, orang Majusi dan orang musyrik, Allah pasti memberi keputusan di antara mereka pada hari Kiamat. Sungguh, Allah menjadi saksi atas segala sesuatu.",
        shortTafsir: "Dalam kehidupan dunia perbedaan agama dan keyakinan itu kadang-kadang tidak terlihat pengaruhnya terhadap keberhasilan dan kegagalan hidup, tetapi berbeda dengan di akhirat. Sesungguhnya orang-orang beriman, orang Yahudi, orang Sabiin, orang Nasrani, orang Majusi dan orang musyrik, nasib mereka di akhirat berbeda. Allah pasti memberi keputusan di antara mereka pada hari Kiamat, orang beriman mendapat rida Allah dan masuk surga, sedangkan orang-orang yang tidak ber-iman mendapat murka Allah dan masuk neraka. Sungguh, Allah menjadi saksi atas segala sesuatu yang terjadi pada diri mereka selama hidup di dunia.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2612",
      ),
      Ayah(
        numberInSurah: 18,
        numberInQuran: 2613,
        juz: 17,
        page: 334,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0633\u0652\u062c\u064f\u062f\u064f \u0644\u064e\u0647\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u0645\u0652\u0633\u064f \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0645\u064e\u0631\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0648\u064e\u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064f \u0648\u064e\u0627\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0628\u0651\u064f \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0647\u0650\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u0650\u0646 \u0645\u0651\u064f\u0643\u0652\u0631\u0650\u0645\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06e9",
        transliteration: "Alam tara annal laaha yasjudu lahoo man fis samaawaati wa man fil ardi wash shamsu walqamaru wan nu joomu wal jibaalu wash shajaru wad dawaaabbu wa kaseerum minan naasi wa kaseerun haqqa 'alaihil 'azaab; wa mai yuhinil laahu famaa lahoo mim mukrim; innallaaha yaf'alu maa yashaaa",
        translation: "Tidakkah engkau tahu bahwa siapa yang ada di langit dan siapa yang ada di bumi bersujud kepada Allah, juga matahari, bulan, bintang, gunung-gunung, pohon-pohon, hewan-hewan yang melata dan banyak di antara manusia? Tetapi banyak (manusia) yang pantas mendapatkan azab. Barangsiapa dihinakan Allah, tidak seorang pun yang akan memuliakannya. Sungguh, Allah berbuat apa saja yang Dia kehendaki.",
        shortTafsir: "Apakah kamu tidak memperhatikan semua yang ada di langit dan semua yang ada di bumi bersujud kepada Allah, tunduk dan patuh kepada hukum alam ciptaan-Nya,\u00a0seperti matahari, bulan,\u00a0dan\u00a0bintang\u00a0yang setia beredar pada porosnya.\u00a0Dan\u00a0juga\u00a0gunung-gunung, pepohonan, dan hewan-hewan melata, semuanya menjalani kehidupan secara alamiah mematuhi hukum alam yang berlaku.\u00a0Dan\u00a0demikian juga,\u00a0banyak di antara manusia\u00a0yang mematuhi hukum Allah karena kesadarannya, tetapi lebih\u00a0banyak\u00a0lagi manusia\u00a0yang pantas mendapatkan azab\u00a0Allah di dunia maupun akhirat, karena sikapnya yang menolak agama Allah.\u00a0Barang siapa dihinakan Allah, karena sikap mereka yang lebih hina dari binatang, maka terhadap manusia yang bersikap demikian,\u00a0tidak seorang pun yang akan memuliakannya\u00a0selain Allah.\u00a0Sungguh, Allah berbuat apa saja yang Dia kehendaki, memuliakan yang layak dimuliakan atau menghinakan yang menutup diri dari petunjuk Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2613",
      ),
      Ayah(
        numberInSurah: 19,
        numberInQuran: 2614,
        juz: 17,
        page: 334,
        arab: "\u06de \u0647\u064e\u0670\u0630\u064e\u0627\u0646\u0650 \u062e\u064e\u0635\u0652\u0645\u064e\u0627\u0646\u0650 \u0627\u062e\u0652\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627 \u0641\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0642\u064f\u0637\u0651\u0650\u0639\u064e\u062a\u0652 \u0644\u064e\u0647\u064f\u0645\u0652 \u062b\u0650\u064a\u064e\u0627\u0628\u064c \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u064d \u064a\u064f\u0635\u064e\u0628\u0651\u064f \u0645\u0650\u0646 \u0641\u064e\u0648\u0652\u0642\u0650 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u0645\u064f",
        transliteration: "Haazaani khasmaanikh tasamoo fee Rabbihim fal lazeena kafaroo qutti'at lahum siyaabum min naar; yusabbu min fawqi ru'oosihimul hameem",
        translation: "Inilah dua golongan (golongan mukmin dan kafir) yang bertengkar, mereka bertengkar mengenai Tuhan mereka. Maka bagi orang kafir akan dibuatkan pakaian-pakaian dari api (neraka) untuk mereka. Ke atas kepala mereka akan disiramkan air yang mendidih.",
        shortTafsir: "Pada ayat 17 Surah al-\u00c8ajj disebutkan enam golongan manusia, orang beriman, Yahudi, Nasrani, Sabiin, Majusi, dan orang-orang musyrik. Mereka sebenarnya terbagi dua. Inilah dua golongan, mukmin dan kafir, yang bertengkar tentang keyakinan. Mereka bertengkar mengenai Tuhan mereka. Maka bagi orang kafir yang menolak prinsip tauhid dari lima golongan di atas, akan dibuatkan untuk mereka di akhirat pakaian-pakaian dari api neraka yang membalut tubuh mereka. Selain itu, ke atas kepala mereka di dalam neraka itu akan disiramkan air yang mendidih hingga tubuh mereka terkelupas.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2614",
      ),
      Ayah(
        numberInSurah: 20,
        numberInQuran: 2615,
        juz: 17,
        page: 334,
        arab: "\u064a\u064f\u0635\u0652\u0647\u064e\u0631\u064f \u0628\u0650\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0644\u064f\u0648\u062f\u064f",
        transliteration: "Yusharu bihee maa fee butoonihim waljulood",
        translation: "Dengan (air mendidih) itu akan dihancurluluhkan apa yang ada dalam perut dan kulit mereka.",
        shortTafsir: "Dengan\u00a0air mendidih yang disiramkan ke atas kepala orang-orang kafir\u00a0itu akan dihancurluluhkan apa yang ada dalam perut dan kulit mereka; kemudian setiap kulit mereka hancur, maka Allah memperbaruinya agar mereka terus merasakan azab Allah.\u00a0Dan\u00a0juga azab\u00a0untuk mereka\u00a0adalah\u00a0cambuk-cambuk dari besi\u00a0untuk memukuli mereka hingga hancur luluh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2615",
      ),
      Ayah(
        numberInSurah: 21,
        numberInQuran: 2616,
        juz: 17,
        page: 334,
        arab: "\u0648\u064e\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0642\u064e\u0627\u0645\u0650\u0639\u064f \u0645\u0650\u0646\u0652 \u062d\u064e\u062f\u0650\u064a\u062f\u064d",
        transliteration: "Wa lahum maqaami'u min hadeed",
        translation: "Dan (azab) untuk mereka cambuk-cambuk dari besi.",
        shortTafsir: "Dengan\u00a0air mendidih yang disiramkan ke atas kepala orang-orang kafir\u00a0itu akan dihancurluluhkan apa yang ada dalam perut dan kulit mereka; kemudian setiap kulit mereka hancur, maka Allah memperbaruinya agar mereka terus merasakan azab Allah.\u00a0Dan\u00a0juga azab\u00a0untuk mereka\u00a0adalah\u00a0cambuk-cambuk dari besi\u00a0untuk memukuli mereka hingga hancur luluh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2616",
      ),
      Ayah(
        numberInSurah: 22,
        numberInQuran: 2617,
        juz: 17,
        page: 334,
        arab: "\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627 \u0623\u064e\u0646 \u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u063a\u064e\u0645\u0651\u064d \u0623\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u0650\u064a\u0642\u0650",
        transliteration: "Kullamaa araadooo any yakhrujoo minhaa min ghammin u'eedoo feeha wa zooqoo 'azaabal hareeq",
        translation: "Setiap kali mereka hendak keluar darinya (neraka) karena tersiksa, mereka dikembalikan (lagi) ke dalamnya. (Kepada mereka dikatakan), \u201cRasakanlah azab yang membakar ini!\u201d",
        shortTafsir: "Setiap kali mereka, para penghuni neraka, berusaha hendak keluar darinya, yakni neraka, karena tersiksa oleh api yang membalut tubuh, air yang mendidih, dan cambuk yang menghancurkan badan, mereka segera dikembalikan lagi ke dalamnya, karena tidak ada jalan untuk keluar dari neraka, apa lagi kembali ke dunia. Lalu kepada mereka akan dikatakan, \u201cRasakanlah azab yang membakar ini sebagai balasan atas kekufuran kamu di dunia!\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2617",
      ),
      Ayah(
        numberInSurah: 23,
        numberInQuran: 2618,
        juz: 17,
        page: 334,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0627\u0631\u064f \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u0652\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0647\u064e\u0628\u064d \u0648\u064e\u0644\u064f\u0624\u0652\u0644\u064f\u0624\u064b\u0627 \u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0631\u0650\u064a\u0631\u064c",
        transliteration: "Innal laaha yudkhilul lazeena aamanoo wa 'amilus saalihaati jannaatin tajree min tahtihal anhaaru yuhallawna feehaa min asaawira min zahabinw wa lu'lu'aa; wa libaasuhum feehaa hareer",
        translation: "Sungguh, Allah akan memasukkan orang-orang yang beriman dan mengerjakan kebajikan ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. Di sana mereka diberi perhiasan gelang-gelang emas dan mutiara, dan pakaian mereka dari sutera.",
        shortTafsir: "Berbeda dengan nasib orang-orang kafir di akhirat,\u00a0sungguh, Allah akan memasukkan orang-orang yang beriman\u00a0yang tidak murtad\u00a0dan mengerjakan kebajikan\u00a0yang bermanfaat bagi dirinya dan orang banyak\u00a0ke dalam surga-surga yang mengalir di bawahnya sungai-sungai\u00a0yang merupakan kenikmatan abadi.\u00a0Di sana mereka diberi perhiasan gelang-gelang emas dan mutiara, dan pakaian mereka\u00a0terbuat\u00a0dari sutera, simbol kebahagiaan dan kenikmatan. Mereka juga mendapat keridaan Allah dan perjum-paan dengan-Nya merupakan kenikmatan tertinggi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2618",
      ),
      Ayah(
        numberInSurah: 24,
        numberInQuran: 2619,
        juz: 17,
        page: 335,
        arab: "\u0648\u064e\u0647\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0648\u064e\u0647\u064f\u062f\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u0650 \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u0650",
        transliteration: "Wa hudooo ilat taiyibi minal qawli wa hudooo ilaaa siraatil hameed",
        translation: "Dan mereka diberi petunjuk kepada ucapan-ucapan yang baik dan diberi petunjuk (pula) kepada jalan (Allah) yang terpuji.",
        shortTafsir: "Dan mereka, para penghuni surga\u00a0diberi petunjuk\u00a0dan bimbingan\u00a0kepada ucapan-ucapan yang baik\u00a0dan santun, serta diberi petunjuk dan bimbingan pula kepada jalan Allah yang Maha Terpuji, berjumpa dan melihat-Nya, karena selama di dunia berakhlak mulia dan berhati bersih.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2619",
      ),
      Ayah(
        numberInSurah: 25,
        numberInQuran: 2620,
        juz: 17,
        page: 335,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0633\u064e\u0648\u064e\u0627\u0621\u064b \u0627\u0644\u0652\u0639\u064e\u0627\u0643\u0650\u0641\u064f \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0627\u062f\u0650 \u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u0652 \u0641\u0650\u064a\u0647\u0650 \u0628\u0650\u0625\u0650\u0644\u0652\u062d\u064e\u0627\u062f\u064d \u0628\u0650\u0638\u064f\u0644\u0652\u0645\u064d \u0646\u0651\u064f\u0630\u0650\u0642\u0652\u0647\u064f \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",
        transliteration: "Innal lazeena kafaroo wa yasuddoona 'an sabeelil laahi wal Masjidil Haraamil lazee ja'alnaahu linnaasi sawaaa'anil 'aakifu feehi walbaad; wa mai yurid feehi bi ilhaadim bizulmin nuziqhu min 'azaabin aleem",
        translation: "Sungguh, orang-orang kafir dan yang menghalangi (manusia) dari jalan Allah dan dari Masjidilharam yang telah Kami jadikan terbuka untuk semua manusia, baik yang bermukim di sana maupun yang datang dari luar dan siapa saja yang bermaksud melakukan kejahatan secara zalim di dalamnya, niscaya akan Kami rasakan kepadanya siksa yang pedih.",
        shortTafsir: "Sungguh, orang-orang kafir Mekah seperti Abu Sufyan bin \u00c8arb dan kawan-kawannya yang menghalangi manusia dari jalan Allah untuk memeluk Islam dan menghalangi Rasulullah dan para sahabat melaksanakan ibadah umrah di Masjidilharam yang telah Kami jadikan terbuka untuk semua manusia yang beriman, baik yang bermukim di sana maupun yang datang dari luar daerah yang jauh; dan siapa saja yang berada di Masjidilharam yang bermaksud melakukan kejahatan seperti membunuh, mengintimidasi, menghalangi manusia masuk Islam, dan berbuat kerusuhan secara zalim di dalamnya, niscaya akan Kami rasakan kepadanya siksa yang pedih di akhirat berupa api yang terus membakar, air mendidih, dan cambuk yang menghancurluluhkan tubuh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2620",
      ),
      Ayah(
        numberInSurah: 26,
        numberInQuran: 2621,
        juz: 17,
        page: 335,
        arab: "\u0648\u064e\u0625\u0650\u0630\u0652 \u0628\u064e\u0648\u0651\u064e\u0623\u0652\u0646\u064e\u0627 \u0644\u0650\u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u0652 \u0628\u064e\u064a\u0652\u062a\u0650\u064a\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u0626\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0626\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0631\u0651\u064f\u0643\u0651\u064e\u0639\u0650 \u0627\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",
        transliteration: "Wa iz bawwaanaa li Ibraaheema makaanal Baiti allaa tushrik bee shai'anw wa tahhir Baitiya litaaa'ifeena walqaaa' imeena warrukka 'is sujood",
        translation: "Dan (ingatlah), ketika Kami tempatkan Ibrahim di tempat Baitullah (dengan mengatakan), \u201cJanganlah engkau mempersekutukan Aku dengan apa pun dan sucikanlah rumah-Ku bagi orang-orang yang tawaf, dan orang yang beribadah dan orang yang rukuk dan sujud.",
        shortTafsir: "Dan\u00a0ingatlah,\u00a0ketika Kami tempatkan Ibrahim\u00a0yang lahir di Kaldea dan menetap di Palestina berada\u00a0di tempat Baitullah, lalu bersama put-ranya, Ismail, meninggikan fondasi Kakbah. Kami menyatakan kepada Ibrahim, \u201cJanganlah engkau mempersekutukan Aku dengan suatu apa pun, karena menyekutukan Allah itu kezaliman yang dahsyat.\u00a0Dan sucikanlah rumah-Ku, Kakbah, dari berhala, kemusyrikan, dan perilaku tidak terpuji, serta peruntukkanlah Kakbah itu\u00a0bagi orang-orang yang tawaf, orang-orang yang beribadah, dan orang yang rukuk dan sujud\u00a0kepada Allah guna mendekatkan diri dan menyucikan jiwa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2621",
      ),
      Ayah(
        numberInSurah: 27,
        numberInQuran: 2622,
        juz: 17,
        page: 335,
        arab: "\u0648\u064e\u0623\u064e\u0630\u0651\u0650\u0646 \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u062c\u0651\u0650 \u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0636\u064e\u0627\u0645\u0650\u0631\u064d \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u062c\u0651\u064d \u0639\u064e\u0645\u0650\u064a\u0642\u064d",
        transliteration: "Wa azzin fin naasi bil Hajji yaatooka rijaalanw wa 'alaa kulli daamiriny yaateena min kulli fajjin 'ameeq",
        translation: "Dan serulah manusia untuk mengerjakan haji, niscaya mereka akan datang kepadamu dengan berjalan kaki, atau mengendarai setiap unta yang kurus, mereka datang dari segenap penjuru yang jauh.",
        shortTafsir: "Dan serulah manusia, wahai Ibrahim, untuk mengerjakan haji mengunjungi Baitullah guna melaksanakan rangkaian manasik haji setelah engkau meninggikan fondasi Kakbah dan membebaskannya dari kemusyrikan, niscaya mereka akan datang kepada seruan-mu sesuai kemampuannya, dengan berjalan kaki bagi yang berjarak dekat, atau mengendarai setiap kuda atau unta yang kurus, karena jauhnya perjalanan menuju Kakbah hingga kehabisan bekal. Mereka datang untuk menunaikan ibadah haji dari segenap penjuru dunia, baik yang dekat maupun yang jauh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2622",
      ),
      Ayah(
        numberInSurah: 28,
        numberInQuran: 2623,
        juz: 17,
        page: 335,
        arab: "\u0644\u0651\u0650\u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0645\u0651\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064e\u0627\u062a\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u06d6 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0628\u064e\u0627\u0626\u0650\u0633\u064e \u0627\u0644\u0652\u0641\u064e\u0642\u0650\u064a\u0631\u064e",
        transliteration: "Li yashhadoo manaafi'a lahum wa yazkurus mal laahi feee ayyaamimma'loomaatin 'alaa maa razaqahum mim baheematil an'aami fakuloo minhaa wa at'imul baaa'isal faqeer",
        translation: "Agar mereka menyaksikan berbagai manfaat untuk mereka dan agar mere-ka menyebut nama Allah pada beberapa hari yang telah ditentukan atas rezeki yang diberikan Dia kepada mereka berupa hewan ternak. Maka makanlah sebagian darinya dan (sebagian lagi) berikanlah untuk dimakan orang-orang yang sengsara dan fakir.",
        shortTafsir: "Dengan memenuhi seruan Nabi Ibrahim, mengunjungi Baitullah guna menunaikan ibadah haji, kaum muslim mendapat keuntungan dunia akhirat, yakni\u00a0agar mereka menyaksikan berbagai manfaat untuk mereka, terutama menguatkan perasaan bersaudara di antara umat muslim,\u00a0dan agar mereka menyebut nama Allah pada beberapa hari yang telah ditentukan\u00a0dalam rangkaian manasik haji seperti berkurban dengan mengumandangkan takbir pada hari raya haji atau hari Tasyriq, yaitu tanggal 10, 11, 12, dan 13 Zulhijah\u00a0atas rezeki yang Dia berikan kepada mereka berupa hewan ternak. Maka makanlah sebagian darinya, sebagai tanda bersyukur dan sebagian lagi\u00a0berikanlah untuk dimakan orang-orang yang sengsara dan fakir\u00a0sebagai tanda peduli dan berbagi dengan kaum duafa hingga perasaan gembira itu dirasakan bersama.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2623",
      ),
      Ayah(
        numberInSurah: 29,
        numberInQuran: 2624,
        juz: 17,
        page: 335,
        arab: "\u062b\u064f\u0645\u0651\u064e \u0644\u0652\u064a\u064e\u0642\u0652\u0636\u064f\u0648\u0627 \u062a\u064e\u0641\u064e\u062b\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0652\u064a\u064f\u0648\u0641\u064f\u0648\u0627 \u0646\u064f\u0630\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u0652\u064a\u064e\u0637\u0651\u064e\u0648\u0651\u064e\u0641\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0627\u0644\u0652\u0639\u064e\u062a\u0650\u064a\u0642\u0650",
        transliteration: "Summal yaqdoo tafasahum wal yoofoo nuzoorahum wal yattawwafoo bil Baitil 'Ateeq",
        translation: "Kemudian, hendaklah mereka menghilangkan kotoran (yang ada di badan) mereka, menyempurnakan nazar-nazar mereka dan melakukan tawaf sekeliling rumah tua (Baitullah).",
        shortTafsir: "Setelah wukuf dilakukan, bermalam di Muzdalifah dan melontar jumrah usai dilaksanakan, maka kemudian\u00a0para tamu Allah hendaklah menghilangkan kotoran yang ada di badan mereka dengan tahalul awal, memotong rambut, kemudian hendaklah mereka menyempurnakan nazar-nazar mereka, jika mereka bernazar, dan melakukan tawaf ifadah sekeliling rumah tua, Baitullah, yang dibangun sejak zaman Adam, kemudian melakukan tahalul kedua yang membolehkan melakukan semua larangan berihram.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2624",
      ),
      Ayah(
        numberInSurah: 30,
        numberInQuran: 2625,
        juz: 17,
        page: 335,
        arab: "\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0639\u064e\u0638\u0651\u0650\u0645\u0652 \u062d\u064f\u0631\u064f\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u0652 \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0627\u0644\u0631\u0651\u0650\u062c\u0652\u0633\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0652\u062b\u064e\u0627\u0646\u0650 \u0648\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0632\u0651\u064f\u0648\u0631\u0650",
        transliteration: "Zaalika wa mai yu'azzim hurumaatil laahi fahuwa khairul lahoo 'inda Rabbih; wa uhillat lakumul an'aamu illaa maa yutlaa 'alaikum fajtanibur rijsa minal awsaani wajtaniboo qawlaz zoor",
        translation: "Demikianlah (perintah Allah). Dan barang siapa mengagungkan apa yang terhormat di sisi Allah (hurumat) maka itu lebih baik baginya di sisi Tuhannya. Dan dihalalkan bagi kamu semua hewan ternak, kecuali yang diterangkan kepadamu (keharamannya), maka jauhilah olehmu (penyembahan) berhala-berhala yang najis itu dan jauhilah perkataan dusta.",
        shortTafsir: "Demikianlah\u00a0perintah Allah kepada kaum muslim untuk melak-sanakan ibadah haji.\u00a0Dan Barang siapa mengagungkan apa yang terhormat di sisi Allah\u00a0dengan melaksanakan rangkaian manasik haji dan menjauhi semua larangan ketika berihram, baik ihram untuk haji maupun umrah,\u00a0maka\u00a0sikap yang demikian\u00a0itu lebih baik baginya, tamu Allah,\u00a0di sisi Tuhannya. Dan dihalalkan bagi kamu semua hewan ternak, baik ketika menunaikan ibadah haji maupun tidak sedang berhaji,\u00a0kecuali yang diterangkan kepadamu\u00a0keharamannya di dalam Al-Qur\u2019an dan Sunah.\u00a0Maka, jauhilah olehmu, wahai orang-orang beriman, penyembahan\u00a0berhala-berhala yang najis itu\u00a0karena tidak sesuai dengan kesucian dan kemurnian tauhid yang diajarkan para nabi dan rasul;\u00a0dan jauhilah perkataan dusta, baik ketika berihram untuk haji atau umrah, lebih-lebih ketika sudah menyandang predikat haji.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2625",
      ),
      Ayah(
        numberInSurah: 31,
        numberInQuran: 2626,
        juz: 17,
        page: 336,
        arab: "\u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u0652\u0631\u064e \u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650 \u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0631\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u062a\u064e\u062e\u0652\u0637\u064e\u0641\u064f\u0647\u064f \u0627\u0644\u0637\u0651\u064e\u064a\u0652\u0631\u064f \u0623\u064e\u0648\u0652 \u062a\u064e\u0647\u0652\u0648\u0650\u064a \u0628\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064f \u0641\u0650\u064a \u0645\u064e\u0643\u064e\u0627\u0646\u064d \u0633\u064e\u062d\u0650\u064a\u0642\u064d",
        transliteration: "Hunafaaa'a lillaahi ghaira mushrikeena bih; wa mai yushrik billaahi faka annamaa kharra minas samaaa'i fatakh tafuhut tairu aw tahwee bihir reehu bee makaanin saheeq",
        translation: "(Beribadahlah) dengan ikhlas kepada Allah, tanpa mempersekutukan-Nya. Barangsiapa mempersekutukan Allah, maka seakan-akan dia jatuh dari langit lalu disambar oleh burung, atau diterbangkan angin ke tempat yang jauh.",
        shortTafsir: "Menunaikan ibadah haji ke Baitullah hendaklah dengan landasan tauhid yang lurus, niat beribadah dengan ikhlas kepada Allah, semata-mata mengharapkan keridaan-Nya, tanpa mempersekutukan-Nya dengan sesuatu apa pun. Barang siapa mempersekutukan Allah, kapan dan di mana pun, selama menunaikan ibadah haji maupun sebelumnya, maka seakan-akan dia jatuh dari langit, karena terputus dari tali Allah hingga ibadahnya tidak diterima, lalu disambar oleh burung hingga dirinya makin jauh dari Allah, atau diterbangkan angin ke tempat yang jauh seperti layang-layang putus.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2626",
      ),
      Ayah(
        numberInSurah: 32,
        numberInQuran: 2627,
        juz: 17,
        page: 336,
        arab: "\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0639\u064e\u0638\u0651\u0650\u0645\u0652 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u062a\u064e\u0642\u0652\u0648\u064e\u0649 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u0650",
        transliteration: "Zaalika wa mai yu'azzim sha'aaa'iral laahi fa innahaa min taqwal quloob",
        translation: "Demikianlah (perintah Allah). Dan barangsiapa mengagungkan syiar-syiar Allah, maka sesungguhnya hal itu timbul dari ketakwaan hati.",
        shortTafsir: "Demikianlah\u00a0perintah Allah agar seorang muslim menunaikan ibadah haji dengan landasan tauhid yang lurus.\u00a0Barang siapa mengagungkan syiar-syiar Allah\u00a0dengan menyempurnakan manasik haji yang dilakukan pada tempat-tempat mengerjakannya dengan hati yang bersih, semata-mata mengharap keridaan-Nya,\u00a0maka sesungguhnya hal itu,\u00a0hanya akan terlaksana bila menunaikan ibadah haji\u00a0timbul dari ketakwaan hati.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2627",
      ),
      Ayah(
        numberInSurah: 33,
        numberInQuran: 2628,
        juz: 17,
        page: 336,
        arab: "\u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0641\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064e\u062c\u064e\u0644\u064d \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u062d\u0650\u0644\u0651\u064f\u0647\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0627\u0644\u0652\u0639\u064e\u062a\u0650\u064a\u0642\u0650",
        transliteration: "Lakum feehaa manaafi'u ilaaa ajalim musamman summa mahilluhaaa ilal Baitil 'Ateeq",
        translation: "Bagi kamu padanya (hewan hadyu) ada beberapa manfaat, sampai waktu yang ditentukan, kemudian tempat penyembelihannya adalah di sekitar Baitul Atiq (Baitullah).",
        shortTafsir: "Bagi kamu yang sedang menunaikan ibadah haji, padanya, yakni pada hewan hadyu yang disembelih sebagai pengganti (dam) pekerjaan wajib haji yang ditinggalkan; atau sebagai denda karena melanggar hal-hal yang terlarang mengerjakannya di dalam ibadah haji, ada beberapa manfaat yang bisa diambil seperti untuk dikendarai, diambil susunya, dan sebagainya, hingga waktu yang ditentukan, yakni hingga hari nahar, tanggal 10 Zulhijah, kemudian tempat penyembelihannya adalah di sekitar Baitul Atiq, Baitullah, di kawasan tanah haram.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2628",
      ),
      Ayah(
        numberInSurah: 34,
        numberInQuran: 2629,
        juz: 17,
        page: 336,
        arab: "\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0646\u0633\u064e\u0643\u064b\u0627 \u0644\u0651\u0650\u064a\u064e\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u0650 \u06d7 \u0641\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0641\u064e\u0644\u064e\u0647\u064f \u0623\u064e\u0633\u0652\u0644\u0650\u0645\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0628\u0650\u062a\u0650\u064a\u0646\u064e",
        transliteration: "Wa likulli ummatin ja'alnaa mansakal liyazkurus mal laahi 'alaa maa razaqahum mim baheematil an'aam; failaahukum ilaahunw Waahidun falahooo aslimoo; wa bashshiril mukhbiteen",
        translation: "Dan bagi setiap umat telah Kami syariatkan penyembelihan (kurban), agar mereka menyebut nama Allah atas rezeki yang dikaruniakan Allah kepada mereka berupa hewan ternak. Maka Tuhanmu ialah Tuhan Yang Maha Esa, karena itu berserahdirilah kamu kepada-Nya. Dan sampaikanlah (Muhammad) kabar gembira kepada orang-orang yang tunduk patuh (kepada Allah),",
        shortTafsir: "Dan bagi setiap umat\u00a0di antara umat para nabi terdahulu\u00a0telah Kami syariatkan penyembelihan\u00a0hewan kurban guna mendekatkan diri kepada Allah,\u00a0agar mereka menyebut nama Allah\u00a0saat menyembelih hewan kurban,\u00a0atas rezeki yang dikaruniakan Allah kepada mereka berupa hewan ternak\u00a0yang dikurbankan.\u00a0Maka\u00a0mantapkanlah dalam ucapan, pikiran, dan perasaan bahwa\u00a0Tuhanmu ialah Tuhan Yang Maha Esa,\u00a0tidak ada sekutu bagi-Nya,\u00a0karena itu berserahdirilah kamu kepada-Nya\u00a0dengan salat yang khusyuk.\u00a0Dan sampaikanlah\u00a0olehmu, Muhammad,\u00a0kabar gembira kepada orang-orang yang tunduk patuh\u00a0kepada Allah bahwa mereka akan mendapat surga.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2629",
      ),
      Ayah(
        numberInSurah: 35,
        numberInQuran: 2630,
        juz: 17,
        page: 336,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062c\u0650\u0644\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0642\u0650\u064a\u0645\u0650\u064a \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Allazeena izaa zukiral laahu wajilat quloobuhum wassaabireena 'alaa maaa asaabahum walmuqeemis Salaati wa mimmaa razaqnaahum yunfiqoon",
        translation: "(yaitu) orang-orang yang apabila disebut nama Allah hati mereka bergetar, orang yang sabar atas apa yang menimpa mereka, dan orang yang melaksanakan salat dan orang yang menginfakkan sebagian rezeki yang Kami karuniakan kepada mereka.",
        shortTafsir: "Mereka yang mantap ketauhidan dan ketundukannya kepada Allah adalah orang-orang yang apabila disebut nama Allah hati mereka bergetar karena kerinduan mereka kepada-Nya; orang-orang yang sabar atas apa yang menimpa mereka, meskipun terasa pahit dan memberatkan punggung mereka; dan orang-orang yang melaksanakan salat wajib dan sunah dengan khusyuk; dan orang-orang yang menginfakkan sebagian rezeki yang Kami karuniakan kepada mereka, baik waktu lapang maupun waktu kekurangan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2630",
      ),
      Ayah(
        numberInSurah: 36,
        numberInQuran: 2631,
        juz: 17,
        page: 336,
        arab: "\u0648\u064e\u0627\u0644\u0652\u0628\u064f\u062f\u0652\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064c \u06d6 \u0641\u064e\u0627\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0635\u064e\u0648\u064e\u0627\u0641\u0651\u064e \u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u062c\u064e\u0628\u064e\u062a\u0652 \u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064e\u0627 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064e\u0627\u0646\u0650\u0639\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0639\u0652\u062a\u064e\u0631\u0651\u064e \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Walbudna ja'alnaahaa lakum min sha'aaa'iril laahi lakum feehaa khairun fazkurusmal laahi 'alaihaa sawaaff; fa izaa wajabat junoobuhaa fakuloo minhaa wa at'imul qaani'a walmu'tarr; kazaalika sakhkharnaahaa lakum la'allakum tashkuroon",
        translation: "Dan unta-unta itu Kami jadikan untuk-mu bagian dari syiar agama Allah, kamu banyak memperoleh kebaikan padanya. Maka sebutlah nama Allah (ketika kamu akan menyembelihnya) dalam keadaan berdiri (dan kaki-kaki telah terikat). Kemudian apabila telah rebah (mati), maka makanlah sebagiannya dan berilah makanlah orang yang merasa cukup dengan apa yang ada padanya (tidak meminta-minta) dan orang yang meminta. Demikianlah Kami tundukkan (unta-unta itu) untukmu, agar kamu bersyukur.",
        shortTafsir: "Dan unta-unta\u00a0yang digemukkan dan diberi kalung untuk dikurbankan\u00a0itu Kami jadikan untuk kamu, para tamu Allah, sebagai\u00a0bagian dari syiar agama Allah, dalam pelaksanaan ibadah haji;\u00a0kamu banyak memperoleh kebaikan\u00a0padanya\u00a0untuk alat transportasi, mengangkut barang, mengambil susu, dan berkurban.\u00a0Maka sebutlah nama Allah\u00a0ketika kamu akan menyembelihnya\u00a0dalam keadaan\u00a0unta-unta itu\u00a0berdiri, karena lazimnya unta disembelih dalam posisi berdiri, dan kaki-kaki-nya telah terikat dengan kuat.\u00a0Kemudian apabila\u00a0unta-unta itu\u00a0telah rebah, selesai disembelih,\u00a0maka makanlah\u00a0oleh kamu\u00a0sebagian dagingnya\u00a0dan\u00a0beri makanlah\u00a0dengan daging unta itu\u00a0orang-orang fakir dan miskin yang merasa cukup dengan apa yang ada padanya, yang tidak meminta-minta karena menjaga kehormatan dirinya,\u00a0dan orang-orang\u00a0fakir dan miskin\u00a0yang meminta-minta\u00a0karena kebutuhan mendesak untuk menjaga kelangsungan hidupnya.\u00a0Demikianlah Kami tundukkan\u00a0unta-unta itu\u00a0untukmu,\u00a0hingga unta-unta itu tidak berontak ketika kamu akan menyembelihnya\u00a0agar kamu bersyukur\u00a0kepada Allah atas karunia-Nya yang diberikan kepada kamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2631",
      ),
      Ayah(
        numberInSurah: 37,
        numberInQuran: 2632,
        juz: 17,
        page: 336,
        arab: "\u0644\u064e\u0646 \u064a\u064e\u0646\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064f\u062d\u064f\u0648\u0645\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062f\u0650\u0645\u064e\u0627\u0624\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f \u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u0643\u064f\u0645\u0652 \u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0644\u0650\u062a\u064f\u0643\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0627\u0643\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Lany yanaalal laaha luhoo muhaa wa laa dimaaa'uhaa wa laakiny yanaaluhut taqwaa minkum; kazaalika sakhkharhaa lakum litukabbirul laaha 'alaa ma hadaakum; wa bashshirul muhsineen",
        translation: "Daging (hewan kurban) dan darahnya itu sekali-kali tidak akan sampai kepada Allah, tetapi yang sampai kepada-Nya adalah ketakwaan kamu. Demi-kianlah Dia menundukkannya untuk-mu agar kamu mengagungkan Allah atas petunjuk yang Dia berikan kepadamu. Dan sampaikanlah kabar gembira kepada orang-orang yang berbuat baik.",
        shortTafsir: "Allah menjelaskan bahwa daging hewan kurban dan darahnya itu sekali-kali tidak akan sampai kepada Allah, karena kurban itu bukan sesajen dan Allah tidak membutuhkan darah dan daging, tetapi yang sampai kepada-Nya adalah ketakwaan kamu, yaitu sikap kamu melawan rasa cinta terhadap harta dan kikir dengan berkurban, peduli, dan berbagi kepada fakir miskin dan duafa guna mendekatkan diri kepada Allah. Demikianlah salah satu tujuan Dia menundukkannya untuk kamu dengan menjinakkan unta-unta itu untuk disembelih agar kamu mengagungkan Allah dengan mengumandangkan takbir ketika menyembelih hewan kurban itu atas petunjuk yang Dia berikan kepadamu dengan mensyariatkan tata cara berkurban, tujuan, dan waktunya. Dan sampaikanlah, oleh kamu Muhammad kabar gembira kepada orang-orang yang berbuat baik yang beriman, berkurban, serta peduli dan berbagi terhadap fakir miskin dan duafa dengan tujuan mengharap keridaan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2632",
      ),
      Ayah(
        numberInSurah: 38,
        numberInQuran: 2633,
        juz: 17,
        page: 336,
        arab: "\u06de \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u064e\u0627\u0641\u0650\u0639\u064f \u0639\u064e\u0646\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u062e\u064e\u0648\u0651\u064e\u0627\u0646\u064d \u0643\u064e\u0641\u064f\u0648\u0631\u064d",
        transliteration: "Innal laaha yudaafi' 'anil lazeena aamanoo; innal laaha laa yuhibbu kulla khawwaanin kafoor",
        translation: "Sesungguhnya Allah membela orang yang beriman. Sungguh, Allah tidak menyukai setiap orang yang berkhianat dan kufur nikmat.",
        shortTafsir: "Orang-orang kafir Mekah dengan segala cara berusaha menghalangi tersebarnya ajaran Islam. Pada ayat ini dijelaskan bahwa\u00a0sesungguhnya Allah membela orang yang beriman\u00a0dengan menguatkan hati mereka untuk bersabar, memiliki daya tahan, menghadapi segala cobaan dan rintangan yang dilakukan orang-orang kafir Mekah tersebut.\u00a0Sungguh, Allah tidak menyukai setiap orang\u00a0beriman\u00a0yang berkhianat\u00a0terhadap agama, sesama orang beriman, serta perjuangan Islam;\u00a0dan\u00a0Allah pun sangat tidak menyukai\u00a0orang-orang yang kufur\u00a0atas nikmat-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2633",
      ),
      Ayah(
        numberInSurah: 39,
        numberInQuran: 2634,
        juz: 17,
        page: 337,
        arab: "\u0623\u064f\u0630\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0635\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u0644\u064e\u0642\u064e\u062f\u0650\u064a\u0631\u064c",
        transliteration: "Uzina lillazeena yuqaataloona bi annahum zulimoo; wa innal laaha 'alaa nasrihim la Qaderr",
        translation: "Diizinkan (berperang) kepada orang-orang yang diperangi, karena sesungguhnya mereka dizalimi. Dan sung-guh, Allah Mahakuasa menolong mereka itu,",
        shortTafsir: "Selama 13 tahun di Mekah Allah membela orang yang beriman dengan menguatkan hati mereka untuk bersabar dalam menghadapi hinaan, boikot, pengusiran dan percobaan pembunuhan yang dilakukan orang-orang kafir. Kini, setelah hijrah ke Madinah, diizinkan kepada orang-orang yang diperangi untuk berperang guna membela diri dan kehormatan agama dalam Perang Badar, karena sesungguhnya mereka dizalimi selama di Mekah. Dan sungguh, Allah Mahakuasa menolong mereka itu pada Perang Badar dengan menurunkan para malaikat untuk mengalahkan orang-orang kafir Mekah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2634",
      ),
      Ayah(
        numberInSurah: 40,
        numberInQuran: 2635,
        juz: 17,
        page: 337,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0627 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0627\u0631\u0650\u0647\u0650\u0645 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u062f\u064e\u0641\u0652\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u064e\u0639\u0652\u0636\u064e\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u0652\u0636\u064d \u0644\u0651\u064e\u0647\u064f\u062f\u0651\u0650\u0645\u064e\u062a\u0652 \u0635\u064e\u0648\u064e\u0627\u0645\u0650\u0639\u064f \u0648\u064e\u0628\u0650\u064a\u064e\u0639\u064c \u0648\u064e\u0635\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u064c \u0648\u064e\u0645\u064e\u0633\u064e\u0627\u062c\u0650\u062f\u064f \u064a\u064f\u0630\u0652\u0643\u064e\u0631\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0627\u0633\u0652\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06d7 \u0648\u064e\u0644\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",
        transliteration: "Allazeena ukhrijoo min diyaarihim bighairi haqqin illaaa any yaqooloo rabbunallaah; wa law laa daf'ul laahin naasa ba'dahum biba'dil lahuddimat sawaami'u wa biya'unw wa salawaatunw wa masaajidu yuzkaru feehasmul laahi kaseeraa; wa layansurannal laahu mai yansuruh; innal laaha la qawiyyun 'Azeez",
        translation: "(yaitu) orang-orang yang diusir dari kampung halamannya tanpa alasan yang benar, hanya karena mereka berkata, \u201cTuhan kami ialah Allah.\u201d Seandainya Allah tidak menolak (keganasan) sebagian manusia dengan sebagian yang lain, tentu telah dirobohkan biara-biara Nasrani, gereja-gereja, rumah-rumah ibadah orang Yahudi dan masjid-masjid, yang di dalamnya banyak disebut nama Allah. Allah pasti akan menolong orang yang menolong (agama)-Nya. Sungguh, Allah Mahakuat, Mahaperkasa.",
        shortTafsir: "Orang-orang beriman yang diizinkan untuk berperang itu adalah\u00a0orang-orang yang diusir dari kampung halamannya\u00a0di Mekah\u00a0tanpa alasan yang benar, baik menurut akal sehat maupun nurani. Alasan satu-satunya dari tindakan tersebut adalah\u00a0hanya karena mereka berkata, \u201cTuhan kami ialah Allah,\u201d lalu istikamah dalam keyakinannya.\u00a0Seandainya Allah tidak menolak\u00a0keganasan\u00a0sebagian manusia kepada sebagian yang lain\u00a0yang menumpahkan darah dan saling menghancurkan, dengan diizinkan berperang kepada orang-orang beriman guna membela diri dan menyadarkan penyerang untuk menghentikan serangannya dan bersedia hidup berdampingan dengan toleran,\u00a0tentu telah dirobohkan biara-biara Nasrani, gereja-gereja, rumah-rumah ibadah orang Yahudi dan masjid-masjid yang di dalamnya banyak disebut nama Allah\u00a0akibat keganasan perang.\u00a0Allah pasti akan menolong orang yang menolong\u00a0agama-Nya dengan mencegah perang dan memperjuangkan perdamaian.\u00a0Sungguh, Allah Mahakuat, Mahaperkasa\u00a0atas segala sesuatu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2635",
      ),
      Ayah(
        numberInSurah: 41,
        numberInQuran: 2636,
        juz: 17,
        page: 337,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0646 \u0645\u0651\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064e\u0648\u064f\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0623\u064e\u0645\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0646\u064e\u0647\u064e\u0648\u0652\u0627 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650",
        transliteration: "Allazeena im makkan naahum fil ardi aqaamus Salaata wa aatawuz Zakaata wa amaroo bilma'roofi wa nahaw 'anil munkar; wa lillaahi 'aaqibatul umoor",
        translation: "(Yaitu) orang-orang yang jika Kami beri kedudukan di bumi, mereka melaksanakan salat, menunaikan zakat, dan menyuruh berbuat yang makruf dan mencegah dari yang mungkar; dan kepada Allah-lah kembali segala urusan.",
        shortTafsir: "Para sahabat Nabi yang diusir dari kampung halamannya hanya karena mereka meyakini tidak ada tuhan selain Allah itu adalah orang-orang yang jika Kami beri kedudukan kepada mereka di bumi dengan menjadi umara, mereka akan menggunakan kekuasaannya untuk mengajak umat melaksanakan salat berjamaah, di masjid, awal waktu; menunaikan zakat, infak, dan sedekah dengan manajemen yang baik untuk kesejahteraan umat, dan menyuruh berbuat yang makruf kepada seluruh lapisan masyarakat dan mencegah dari yang mungkar dari siapa saja yang mengindikasikan melanggar hukum dan menyimpang dari aturan yang berlaku; dan kepada Allah-lah kembali segala urusan dengan seadil-adilnya mengenai nasib manusia di akhirat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2636",
      ),
      Ayah(
        numberInSurah: 42,
        numberInQuran: 2637,
        juz: 17,
        page: 337,
        arab: "\u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0648\u064e\u0639\u064e\u0627\u062f\u064c \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f",
        transliteration: "Wa iny yukazzibooka faqad kazzabat qablahum qawmu Nooinw wa Aadunw wa Samood",
        translation: "Dan jika mereka (orang-orang musyrik) mendustakan engkau (Muhammad), begitu pulalah kaum-kaum yang sebelum mereka, kaum Nuh, \u2018Ad, dan Samud (juga telah mendustakan rasul-rasul-Nya),",
        shortTafsir: "Dan jika mereka, orang-orang musyrik yang kaya dan berkuasa di Mekah,\u00a0mendustakan\u00a0ajaran\u00a0engkau, Muhammad, yang bersumber dari wahyu Allah,\u00a0maka sungguh begitulah\u00a0sikap kaum\u00a0sebelum mereka, mendustakan ajaran yang dibawa oleh para nabi mereka seperti\u00a0kaum Nuh, \u2018Ad, dan Samud, dan\u00a0demikian juga sifat dan karakter\u00a0kaum Ibrahim dan kaum Lut\u00a0yang secara terbuka menantang dan mendustakan ajaran para nabi yang diutus kepada mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2637",
      ),
      Ayah(
        numberInSurah: 43,
        numberInQuran: 2638,
        juz: 17,
        page: 337,
        arab: "\u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d",
        transliteration: "Wa qawmu Ibraaheema wa qawmu Loot",
        translation: "dan (demikian juga) kaum Ibrahim dan kaum Lut,",
        shortTafsir: "Dan jika mereka, orang-orang musyrik yang kaya dan berkuasa di Mekah,\u00a0mendustakan\u00a0ajaran\u00a0engkau, Muhammad, yang bersumber dari wahyu Allah,\u00a0maka sungguh begitulah\u00a0sikap kaum\u00a0sebelum mereka, mendustakan ajaran yang dibawa oleh para nabi mereka seperti\u00a0kaum Nuh, \u2018Ad, dan Samud, dan\u00a0demikian juga sifat dan karakter\u00a0kaum Ibrahim dan kaum Lut\u00a0yang secara terbuka menantang dan mendustakan ajaran para nabi yang diutus kepada mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2638",
      ),
      Ayah(
        numberInSurah: 44,
        numberInQuran: 2639,
        juz: 17,
        page: 337,
        arab: "\u0648\u064e\u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u06d6 \u0648\u064e\u0643\u064f\u0630\u0651\u0650\u0628\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0623\u064e\u0645\u0652\u0644\u064e\u064a\u0652\u062a\u064f \u0644\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",
        transliteration: "Wa as haabu Madyana wa kuzziba Moosaa fa amlaitu lilkaafireena summa akhaztuhum fakaifa kaana nakeer",
        translation: "dan penduduk Madyan. Dan Musa (juga) telah didustakan, namun Aku beri tenggang waktu kepada orang-orang kafir, kemudian Aku siksa mereka, maka betapa hebatnya siksaan-Ku.",
        shortTafsir: "Dan demikian pula penduduk Madyan telah menustakan ajaran Nabi Syu\u2018aib. Dan\u00a0ajaran Nabi Musa juga telah didustakan oleh Firaun dan Bani Israil, maka Aku telah memberikan tenggang waktu kepada orang-orang kafir dengan memanjangkan umur mereka di dunia, kemudian Aku menyiksa mereka di akhirat dengan merasakan azab-Ku di dalam neraka, maka betapa hebatnya siksaan-Ku yang dirasakan oleh mereka yang menolak ajaran-Ku yang dibawa oleh para rasul.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2639",
      ),
      Ayah(
        numberInSurah: 45,
        numberInQuran: 2640,
        juz: 17,
        page: 337,
        arab: "\u0641\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u064c \u0641\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u0650\u0626\u0652\u0631\u064d \u0645\u0651\u064f\u0639\u064e\u0637\u0651\u064e\u0644\u064e\u0629\u064d \u0648\u064e\u0642\u064e\u0635\u0652\u0631\u064d \u0645\u0651\u064e\u0634\u0650\u064a\u062f\u064d",
        transliteration: "Faka ayyim min qaryatin ahlaknaahaa wa hiya zaalimatun fahiya khaawiyatun 'alaa 'urooshihaa wa bi'rim mu'at talatinw wa qasrim masheed",
        translation: "Maka betapa banyak negeri yang telah Kami binasakan karena (penduduk)nya dalam keadaan zalim, sehingga runtuh bangunan-bangunannya dan (betapa banyak pula) sumur yang telah ditinggalkan dan istana yang tinggi (ti-dak ada penghuninya).",
        shortTafsir: "Allah menurunkan adzabnya kepada umat-umat terdahulu yang telah mendustakan dan mengingkari ajaran para rasul-Nya yang diutus kepada mereka. \"Maka, betapa banyak negeri yang telah Kami binasakan, karena\u00a0penduduknya\u00a0dalam keadaan zalim\u00a0terhadap diri mereka sendiri dengan tidak beriman dan bertindak sewenang-wenang terhadap para rasul, menghina, mendustakan, dan membunuh mereka, lalu kami mengazab mereka\u00a0sehingga runtuhlah bangunan-bangunannya; dan betapa banyak pula\u00a0sumur yang telah ditinggalkan, karena penduduk negeri itu telah binasa;\u00a0dan istana yang tinggi, mewah dan indah telah menjadi rumah tua yang tidak ada penghuninya,\" demikian Allah menjelaskan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2640",
      ),
      Ayah(
        numberInSurah: 46,
        numberInQuran: 2641,
        juz: 17,
        page: 337,
        arab: "\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064c \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0622\u0630\u064e\u0627\u0646\u064c \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0628\u0652\u0635\u064e\u0627\u0631\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u062a\u064e\u0639\u0652\u0645\u064e\u0649 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",
        transliteration: "Afalam yaseeroo fil ardi fatakoona lahum quloobuny ya'qiloona bihaaa aw aazaanuny yasm'oona bihaa fa innahaa laa ta'mal absaaru wa laakin ta'mal quloobul latee fissudoor",
        translation: "Maka tidak pernahkah mereka berjalan di bumi, sehingga hati (akal) mereka dapat memahami, telinga mereka dapat mendengar? Sebenarnya bukan mata itu yang buta, tetapi yang buta ialah hati yang di dalam dada.",
        shortTafsir: "Allah lalu bertanya kepada orang-orang yang menolak ajaran Allah yang dibawa Rasulullah, \"Maka apakah mereka tidak pernah berjalan di bumi menyaksikan peninggalan umat terdahulu atau mengkajinya secara mendalam sehingga kalbu, kecerdasan emosi, dan spiritual mereka dapat memahami atau merenungkan ajaran Al-Qur\u2019an atau telinga mereka dapat mendengar ajakan Rasul untuk beriman kepada Allah?\" Mata, telinga, dan pikiran mereka tertutup. Oleh sebab itu, sejatinya bukan mata lahiriah mereka itu yang buta sehingga tidak dapat melihat bukti-bukti kebenaran ajaran Rasulullah, tetapi yang buta adalah mata hati mereka yang ada di dalam dada mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2641",
      ),
      Ayah(
        numberInSurah: 47,
        numberInQuran: 2642,
        juz: 17,
        page: 338,
        arab: "\u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0644\u064e\u0646 \u064a\u064f\u062e\u0652\u0644\u0650\u0641\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u0623\u064e\u0644\u0652\u0641\u0650 \u0633\u064e\u0646\u064e\u0629\u064d \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0646\u064e",
        transliteration: "Wa yasta'juloonaka bil'azaabi wa lany yukhlifal laahu wa'dah; wa inna yawman 'inda Rabbika ka'alfi sanatim mimmaa ta'uddoon",
        translation: "Dan mereka meminta kepadamu (Muhammad) agar azab itu disegerakan, padahal Allah tidak akan menyalahi janji-Nya. Dan sesungguhnya sehari di sisi Tuhanmu adalah seperti seribu tahun menurut perhitunganmu.",
        shortTafsir: "Karena mata hati mereka buta dan telinga mereka tertutup,\u00a0dan mereka\u00a0dengan sombong dan menantang\u00a0meminta kepadamu, Muhammad,\u00a0agar azab\u00a0yang dijanjikan kepada orang-orang kafir\u00a0itu disegerakan\u00a0di dunia ini. Mereka tidak mengetahui\u00a0bahwa Allah tidak akan pernah menyalahi janji-Nya\u00a0bahwa azab yang pedih bagi orang-orang kafir itu akan diberikan di akhirat.\u00a0Dan sungguh, jika mereka menyadari\u00a0bahwa sehari di sisi Tuhanmu\u00a0di akhirat\u00a0seperti seribu tahun menurut perhitunganmu\u00a0di dunia sehingga merasakan azab sehari saja di dalam neraka sebanding dengan seribu tahun di dunia. Betapa dah-syatnya azab Allah, mengapa mereka menantang?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2642",
      ),
      Ayah(
        numberInSurah: 48,
        numberInQuran: 2643,
        juz: 17,
        page: 338,
        arab: "\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0623\u064e\u0645\u0652\u0644\u064e\u064a\u0652\u062a\u064f \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u064c \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",
        transliteration: "Wa ka ayyim min qaryatin amlaitu lahaa wa hiya zaalimatun summa akhaztuhaa wa ilaiyal maseer",
        translation: "Dan berapa banyak negeri yang Aku tangguhkan (penghancuran)nya, karena penduduknya berbuat zalim, kemudian Aku azab mereka, dan hanya kepada-Kulah tempat kembali (segala sesuatu).",
        shortTafsir: "Tantangan orang kafir agar disegerakan pemberian azab bagi me-reka dijawab Allah dengan berfirman, \"Dan perhatikanlah, berapa banyak negeri yang Aku tangguhkan penghancurannya, meskipun penduduknya meminta agar azab yang dijanjikan itu disegerakan. Karena penduduknya berbuat zalim, tidak beriman, menghina, dan mengusir utusan Allah, kemudian Aku azab mereka saat mereka merasa aman dari azab-Ku. Dan hanya kepada-Kulah tempat kembali setiap orang dalam kehidupan sesudah mati, baik yang beriman maupun yang kufur.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2643",
      ),
      Ayah(
        numberInSurah: 49,
        numberInQuran: 2644,
        juz: 17,
        page: 338,
        arab: "\u0642\u064f\u0644\u0652 \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",
        transliteration: "Qul yaaa ayyuhan naasu innamaaa ana lakum nazeerum mubeen",
        translation: "Katakanlah (Muhammad), \u201cWahai manusia! Sesungguhnya aku (diutus) kepadamu sebagai pemberi peringatan yang nyata.\u201d",
        shortTafsir: "Orang-orang musyrik Mekah, sebagaimana disebutkan pada ayat di atas, mengolok-olok Rasulullah dengan meminta disegerakan datangnya azab. Pada ayat ini disebutkan bahwa tugas beliau adalah menyampaikan peringatan.\u00a0Katakanlah\u00a0olehmu, Muhammad, \u201cWahai manusia! Urusan menurunkan azab itu wewenang Allah.\u00a0Sesungguhnya aku\u00a0diutus\u00a0kepadamu\u00a0dan seluruh manusia hingga hari Kiamat\u00a0sebagai pemberi peringatan yang nyata\u00a0bahwa beriman akan mendapatkan rida Allah, sedangkan mendustakan akan mendapatkan murka-Nya.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2644",
      ),
      Ayah(
        numberInSurah: 50,
        numberInQuran: 2645,
        juz: 17,
        page: 338,
        arab: "\u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064c \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c",
        transliteration: "Fallazeena aamanoo wa 'amilu saalihaati lahum maghfiratunw wa rizqun kareem",
        translation: "Maka orang-orang yang beriman dan mengerjakan kebajikan, mereka memperoleh ampunan dan rezeki yang mulia.",
        shortTafsir: "Maka orang-orang yang beriman kepada Allah dan Rasul-Nya, serta mengharumkan Islam dan mengerjakan kebajikan yang bermanfaat bagi manusia dan kemanusiaan, mereka akan memperoleh ampunan dari Allah atas dosa-dosa yang dilakukannya dan akan memperoleh rezeki yang mulia di akhirat dengan dimasukkan ke dalam surga, tempat penuh kenikmatan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2645",
      ),
      Ayah(
        numberInSurah: 51,
        numberInQuran: 2646,
        juz: 17,
        page: 338,
        arab: "\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0627\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u0650",
        transliteration: "Wallazeena sa'aw feee Aayaatinaa mu'aajizeena ulaaa ika As-haabul jaheem",
        translation: "Tetapi orang-orang yang berusaha menentang ayat-ayat Kami dengan maksud melemahkan (kemauan untuk beriman), mereka itu adalah penghuni-penghuni neraka Jahim.",
        shortTafsir: "Tetapi orang-orang yang berusaha menentang ayat-ayat Kami\u00a0dengan segala cara\u00a0dengan maksud melemahkan\u00a0niat dan dorongan penduduk Mekah yang akan beriman kepada Allah dan Rasul-Nya, maka\u00a0mereka itu\u00a0di akhirat adalah calon\u00a0penghuni neraka Jahim.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2646",
      ),
      Ayah(
        numberInSurah: 52,
        numberInQuran: 2647,
        juz: 17,
        page: 338,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0649\u0670 \u0623\u064e\u0644\u0652\u0642\u064e\u0649 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u0650\u064a \u0623\u064f\u0645\u0652\u0646\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650 \u0641\u064e\u064a\u064e\u0646\u0633\u064e\u062e\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064f\u0644\u0652\u0642\u0650\u064a \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u0643\u0650\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u06d7 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",
        transliteration: "Wa maaa arsalnaa min qablika mir Rasoolinnw wa laa Nabiyyin illaaa izaaa tamannaaa alqash Shaitaanu feee umniy yatihee fa yansakhul laahu maa yulqish Shaitaanu summa yuhkimul laahu aayaatih; wallaahu 'Aleemun Hakeem",
        translation: "Dan Kami tidak mengutus seorang rasul dan tidak (pula) seorang nabi sebelum engkau (Muhammad), mela-inkan apabila dia mempunyai suatu keinginan, setan pun memasukkan godaan-godaan ke dalam keinginannya itu. Tetapi Allah menghilangkan apa yang dimasukkan setan itu, dan Allah akan menguatkan ayat-ayat-Nya. Dan Allah Maha Mengetahui, Mahabijaksana,",
        shortTafsir: "Setelah dijelaskan bagaimana orang kafir menantang ayat-ayat Allah, pada ayat ini dijelaskan usaha setan melemahkan ayat-Nya, ketika ayat itu diwahyukan kepada para nabi dan rasul. Dan Kami tidak mengutus seorang rasul pun di antara rasul-rasul Allah, dan tidak pula seorang nabi sebelum engkau Muhammad, melainkan apabila dia mempunyai suatu keinginan untuk memberi peringatan kepada orang-orang kafir, mereka segera mengikuti bacaan Nabi dengan tambahan kata-kata yang membenarkan keyakinan mereka melalui usaha setan memasukkan kata-kata sesat ke dalam bacaan itu. Akan tetapi usaha ini tidak akan pernah berhasil. karena Allah segera menghilangkan apa yang dimasukkan setan itu dengan cepat; dan Allah akan menguatkan ayat-ayat-Nya pada jiwa Rasulullah dengan melindungi beliau dari kemungkinan menyampaikan kata-kata setan. Dan Allah Maha Mengetahui atas segala sesuatu, lagi Mahabijaksana dalam semua perbuatan-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2647",
      ),
      Ayah(
        numberInSurah: 53,
        numberInQuran: 2648,
        juz: 17,
        page: 338,
        arab: "\u0644\u0651\u0650\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064e \u0645\u064e\u0627 \u064a\u064f\u0644\u0652\u0642\u0650\u064a \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064f \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064b \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u064c \u0648\u064e\u0627\u0644\u0652\u0642\u064e\u0627\u0633\u0650\u064a\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u064d \u0628\u064e\u0639\u0650\u064a\u062f\u064d",
        transliteration: "Liyaj'ala maa yulqish Shaitaanu fitnatal lillazeena fee quloobihim maradunw walqaasiyati quloobuhum; wa innaz zaalimeena lafee shiqaaqim ba'eed",
        translation: "Dia (Allah) ingin menjadikan godaan yang ditimbulkan setan itu, sebagai cobaan bagi orang-orang yang dalam hatinya ada penyakit dan orang yang berhati keras. Dan orang-orang yang zalim itu benar-benar dalam permu-suhan yang jauh,",
        shortTafsir: "Allah mengizinkan setan menyisipkan kata-kata sesat ke dalam ayat-ayat-Nya ketika diwahyukan, karena\u00a0Dia ingin menjadikan kata-kata sesat yang ditimbulkan setan itu sebagai cobaan\u00a0yang bisa menyesatkan,\u00a0bagi orang-orang yang lemah iman\u00a0yaitu\u00a0bagi orang-orang yang dalam hatinya ada penyakit\u00a0kemunafikan\u00a0dan orang yang berhati keras\u00a0sehingga tertutup dari cahaya Allah.\u00a0Dan sungguh orang-orang yang zalim itu, karena meyakini kata-kata setan itu bagian dari wahyu Allah,\u00a0benar-benar dalam permusuhan\u00a0terhadap Allah dan Rasul-Nya\u00a0yang jauh\u00a0dari kebenaran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2648",
      ),
      Ayah(
        numberInSurah: 54,
        numberInQuran: 2649,
        juz: 17,
        page: 338,
        arab: "\u0648\u064e\u0644\u0650\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0641\u064e\u062a\u064f\u062e\u0652\u0628\u0650\u062a\u064e \u0644\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064e\u0627\u062f\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u0651\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",
        transliteration: "Wa liya'lamal lazeena ootul 'ilma annahul haqqu mir Rabbika fa yu'minoo bihee fatukhbita ahoo quloobuhum; wa innal laaha lahaadil lazeena aamanoo ilaa Siraatim Mustaqeem",
        translation: "dan agar orang-orang yang telah diberi ilmu, meyakini bahwa (Al-Qur'an) itu benar dari Tuhanmu lalu mereka beriman dan hati mereka tunduk kepadanya. Dan sungguh, Allah pemberi petunjuk bagi orang-orang yang beriman kepada jalan yang lurus.",
        shortTafsir: "Penjelasan Allah di dua ayat di atas bertujuan agar orang-orang yang telah diberi ilmu akal dan ilmu kalbu meyakini bahwa Al-Qur\u2019an itu benar dari Tuhanmu, tidak akan pernah bisa disusupi kata-kata setan; lalu mereka beriman kepada Al-Qur\u2019an dengan mantap; dan hati mereka pun tunduk kepadanya tanpa ada keraguan sedikit pun. Dan sungguh, Allah adalah Maha Pemberi Petunjuk bagi orang-orang beriman kepada jalan yang lurus, agama Islam yang hanif, karena pikiran, perasaan, dan ruhaninya tercerahkan dengan cahaya Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2649",
      ),
      Ayah(
        numberInSurah: 55,
        numberInQuran: 2650,
        juz: 17,
        page: 338,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0645\u0650\u0631\u0652\u064a\u064e\u0629\u064d \u0645\u0651\u0650\u0646\u0652\u0647\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u0652 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0642\u0650\u064a\u0645\u064d",
        transliteration: "Wa laa yazaalul lazeena kafaroo fee miryatim minhu hattaa taatiyahumus Saa'atu baghtatan aw yaatiyahum 'azaabu Yawmin 'aqeem",
        translation: "Dan orang-orang kafir itu senantiasa ragu mengenai hal itu (Al-Qur'an), hingga saat (kematiannya) datang kepada mereka dengan tiba-tiba, atau azab hari Kiamat yang datang kepada mereka.",
        shortTafsir: "Berbeda dengan orang-orang yang diberi ilmu, lalu beriman kepada Al-Qur\u2019an dengan mantap, bahwa\u00a0orang-orang kafir itu senantiasa ragu mengenai\u00a0Al-Qur\u2019an dengan keraguan yang terus-menerus\u00a0hingga saat\u00a0kematian\u00a0datang kepada mereka dengan tiba-tiba, atau\u00a0bahkan keraguan mereka itu terbawa hingga merasakan\u00a0azab hari Kiamat yang datang kepada mereka\u00a0dengan cepat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2650",
      ),
      Ayah(
        numberInSurah: 56,
        numberInQuran: 2651,
        juz: 17,
        page: 339,
        arab: "\u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u06da \u0641\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",
        transliteration: "Almulku Yawma'izil lillaahi yahkumu bainahum; fallazeena aamanoo wa 'amilus saalihaati fee jannaatin Na'eem",
        translation: "Kekuasaan pada hari itu ada pada Allah, Dia memberi keputusan di an-tara mereka. Maka orang-orang yang beriman dan mengerjakan kebajikan berada dalam surga-surga yang penuh kenikmatan.",
        shortTafsir: "Pada ayat ini ditegaskan, baik orang yang beriman kepada Al-Qur\u2019an maupun yang kufur, pada hari Kiamat kehilangan kekuasaannya.\u00a0Kekuasaan pada hari itu hanya ada pada Allah.\u00a0Pada hari itu dengan keadilan-Nya,\u00a0Dia memberi keputusan di antara mereka\u00a0yang beriman dan yang kufur dengan seadil-adilnya.\u00a0Maka orang-orang yang beriman dan mengerjakan kebajikan\u00a0selama hidupnya di dunia\u00a0berada dalam surga-surga yang penuh kenikmatan\u00a0yang kekal selama-lamanya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2651",
      ),
      Ayah(
        numberInSurah: 57,
        numberInQuran: 2652,
        juz: 17,
        page: 339,
        arab: "\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u064c",
        transliteration: "Wallazeena kafaroo wa kazzaboo bi Aayaatinaa fa ulaaa'ika lahum 'azaabum muheen",
        translation: "Dan orang-orang kafir dan yang men-dustakan ayat-ayat Kami, maka mere-ka akan merasakan azab yang meng-hinakan.",
        shortTafsir: "Sedangkan orang-orang yang kafir\u00a0kepada Allah dan Rasul-Nya\u00a0dan\u00a0orang-orang\u00a0yang mendustakan ayat-ayat Kami\u00a0dengan mengolok-olokkannya,\u00a0maka mereka\u00a0di akhirat\u00a0akan merasakan azab\u00a0yang menghinakan\u00a0dan mereka kekal selama-lamanya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2652",
      ),
      Ayah(
        numberInSurah: 58,
        numberInQuran: 2653,
        juz: 17,
        page: 339,
        arab: "\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0652 \u0645\u064e\u0627\u062a\u064f\u0648\u0627 \u0644\u064e\u064a\u064e\u0631\u0652\u0632\u064f\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u0627\u0632\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Wallazeena haajaroo fee sabeelil laahi summa qutilooo law maatoo la yarzuqan nahumul laahu rizqan hasanaa; wa innal laaha la Huwa khairur raaziqeen",
        translation: "Dan orang-orang yang berhijrah di jalan Allah, kemudian mereka terbunuh atau mati, sungguh, Allah akan memberikan kepada mereka rezeki yang baik (surga). Dan sesungguhnya Allah adalah pemberi rezeki yang terbaik.",
        shortTafsir: "Pada ayat yang lalu diterangkan bahwa Allah selalu menjaga Rasul, kemurnian Al-Qur\u2019an, dan memberi balasan yang adil di akhirat. Pada ayat ini dijelaskan balasan bagi orang yang meninggal ketika hijrah pada jalan Allah. Dan orang-orang beriman yang berhijrah di jalan Allah, mengubah pola hidup yang buruk dengan pola hidup Islami, kemudian mereka terbunuh ketika memperjuangkan perubahan itu atau mati secara normal; sungguh, Allah akan memberikan kepada mereka, baik yang terbunuh maupun yang meninggal biasa, rezeki yang baik, berupa surga de-ngan segala kenikmatannya, yang kekal. Dan sesungguhnya Allah adalah pemberi rezeki yang terbaik kepada siapa saja di antara hamba-hamba-Nya yang beriman dan berhijrah pada jalan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2653",
      ),
      Ayah(
        numberInSurah: 59,
        numberInQuran: 2654,
        juz: 17,
        page: 339,
        arab: "\u0644\u064e\u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u062f\u0652\u062e\u064e\u0644\u064b\u0627 \u064a\u064e\u0631\u0652\u0636\u064e\u0648\u0652\u0646\u064e\u0647\u064f \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",
        transliteration: "La yudkhilan nahum mud khalany yardawnah; wa innal laaha la 'Aleemun Haleem",
        translation: "Sungguh, Dia (Allah) pasti akan memasukkan mereka ke tempat masuk (surga) yang mereka sukai. Dan sesungguhnya Allah Maha Mengetahui, Maha Penyantun.",
        shortTafsir: "Rezeki baik yang disebut ayat di atas adalah surga.\u00a0Sungguh,\u00a0Allah\u00a0pasti akan memasukkan mereka, orang beriman yang berhijrah pada jalan-Nya,\u00a0ke tempat masuk,\u00a0yakni surga dengan segala kenikmatannya\u00a0yang mereka sukai. Dan sesungguhnya Allah Maha Mengetahui\u00a0segala sesuatu,\u00a0Maha Penyantun\u00a0kepada hamba-hamba-Nya yang beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2654",
      ),
      Ayah(
        numberInSurah: 60,
        numberInQuran: 2655,
        juz: 17,
        page: 339,
        arab: "\u06de \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u0642\u064e\u0628\u064e \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0645\u064e\u0627 \u0639\u064f\u0648\u0642\u0650\u0628\u064e \u0628\u0650\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0628\u064f\u063a\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0644\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0641\u064f\u0648\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u064c",
        transliteration: "Zaalika wa man 'aaqaba bimisli maa 'ooqiba bihee summa bughiya 'alaihi la yansurannahul laah; innal laaha la 'Afuwwun Ghafoor",
        translation: "Demikianlah, dan barangsiapa membalas seimbang dengan (kezaliman) penganiayaan yang pernah dia derita kemudian dia dizalimi (lagi), pasti Allah akan menolongnya. Sungguh, Allah Maha Pemaaf, Maha Pengampun.",
        shortTafsir: "Orang beriman boleh melakukan perlawanan atau pembelaan diri jika dizalimi. Demikianlah, Allah mengizinkan kepada orang-orang beriman untuk membela diri dengan adil, dan barang siapa membalas perlakuan zalim sebanding dengan kezaliman atau penganiayaan yang pernah dia derita di masa lalu, kemudian dia dizalimi lagi, karena mempertahankan hak, pasti Allah akan menolongnya di dunia maupun di akhirat. Sungguh, Allah Maha Pemaaf kepada hamba-hamba-Nya yang memaafkan kesalahan orang lain, Maha Pengampun kepada mereka yang bertobat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2655",
      ),
      Ayah(
        numberInSurah: 61,
        numberInQuran: 2656,
        juz: 17,
        page: 339,
        arab: "\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",
        transliteration: "Zaalika bi annal laaha yoolijul laila fin nahaari wa yoolijun nahaara fil laili wa annal laaha Samee'um Baseer",
        translation: "Demikianlah karena Allah (kuasa) memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan sungguh, Allah Maha Mendengar, Maha Melihat.",
        shortTafsir: "Untuk memberi pertolongan kepada orang-orang beriman yang dizalimi pasti akan ditepati.\u00a0Demikianlah, janji Allah,\u00a0karena Allah\u00a0berkuasa\u00a0memasukkan malam ke dalam siang\u00a0sehingga siang di musim panas lebih panjang,\u00a0dan memasukkan siang ke dalam malam\u00a0sehingga malam lebih panjang di musim dingin;\u00a0dan sungguh, Allah Maha Mendengar\u00a0doa setiap hamba dan\u00a0Maha Melihat\u00a0keberadaan seluruh makhluk-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2656",
      ),
      Ayah(
        numberInSurah: 62,
        numberInQuran: 2657,
        juz: 17,
        page: 339,
        arab: "\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",
        transliteration: "Zaalika bi annal laaha Huwal haqqu wa anna maa yad'oona min doonihee huwal baatilu wa annal laaha Huwal 'Aliyyul kabeer",
        translation: "Demikianlah (kebesaran Allah) karena Allah, Dialah (Tuhan) Yang Hak. Dan apa saja yang mereka seru selain Dia, itulah yang batil, dan sungguh Allah, Dialah Yang Mahatinggi, Mahabesar.",
        shortTafsir: "Demikianlah, Allah memperlihatkan kekuasaan-Nya memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam,\u00a0karena Allah, Dialah\u00a0Tuhan\u00a0yang Hak\u00a0sehingga hanya Dia yang berhak disembah.\u00a0Dan sungguh apa saja yang mereka seru selain Dia\u00a0yang dianggap tuhan dan disembah,\u00a0itulah\u00a0tuhan dan persembahan\u00a0yang batil, salah, sesat, dan jauh dari kebenaran;\u00a0dan sungguh Allah, Dialah Yang Mahatinggi\u00a0dari semua tuhan-tuhan yang dianggap tinggi oleh manusia;\u00a0Mahabesar,\u00a0kekuasaan-Nya atas segala sesuatu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2657",
      ),
      Ayah(
        numberInSurah: 63,
        numberInQuran: 2658,
        juz: 17,
        page: 339,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0645\u064e\u0627\u0621\u064b \u0641\u064e\u062a\u064f\u0635\u0652\u0628\u0650\u062d\u064f \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064f \u0645\u064f\u062e\u0652\u0636\u064e\u0631\u0651\u064e\u0629\u064b \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u064c",
        transliteration: "Alam tara annal laaha anzala minas samaaa'i maaa'an fatusbihul ardu mukhdarrah; innal laaha Lateefun Khabeer",
        translation: "Tidakkah engkau memperhatikan, bahwa Allah menurunkan air (hujan) dari langit, sehingga bumi menjadi hijau? Sungguh, Allah Mahahalus, Maha Mengetahui.",
        shortTafsir: "Tidakkah engkau memperhatikan\u00a0fenomena alam semesta, termasuk siklus air yang terjadi dalam kehidupan kita,\u00a0bahwa Allah menurunkan air\u00a0hujan\u00a0dari langit, kemudian sebagian air itu tersimpan pada pepohonan\u00a0sehingga bumi menjadi hijau? Sungguh, Allah Mahahalus\u00a0kasih sayang-Nya dengan menyediakan oksigen dan protein nabati yang diperlukan seluruh makhluk hidup,\u00a0Maha Mengetahui\u00a0segala sesuatu, termasuk yang paling dibutuhkan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2658",
      ),
      Ayah(
        numberInSurah: 64,
        numberInQuran: 2659,
        juz: 17,
        page: 339,
        arab: "\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",
        transliteration: "Lahoo ma fis samaawaati wa ma fil ard; wa innal laaha la Huwal Ghaniyyul Hameed",
        translation: "Milik-Nyalah apa yang ada di langit dan apa yang ada di bumi. Dan Allah benar-benar Mahakaya, Maha Terpuji.",
        shortTafsir: "Oleh karena itu, Allah benar-benar Tuhan Yang Mengelola dan Maha Berkuasa atas jagat raya. Milik-Nyalah apa yang ada di langit dan apa yang ada di bumi sehingga tidak satu pun peristiwa yang terjadi di keduanya di luar kekuasaan-Nya. Dan Allah benar-benar Mahakaya, karena Dia pemilik mutlak langit dan bumi dengan segala isinya, Maha Terpuji, karena Dia sangat lembut kepada makhluk-Nya dan sangat teratur ciptaan-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2659",
      ),
      Ayah(
        numberInSurah: 65,
        numberInQuran: 2660,
        juz: 17,
        page: 340,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u064e \u062a\u064e\u062c\u0652\u0631\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u0650 \u0628\u0650\u0623\u064e\u0645\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u064a\u064f\u0645\u0652\u0633\u0650\u0643\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u064e \u0623\u064e\u0646 \u062a\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",
        transliteration: "Alam tara annal laaha sakhkhara lakum maa fil ardi wal fulka tajree fil bahri bi amrihee wa yumsikus samaaa'a an taqa'a 'alal ardi illaa biiznih; innal laaha binnaasi la Ra'oofur Raheem",
        translation: "Tidakkah engkau memperhatikan bahwa Allah menundukkan bagimu (manusia) apa yang ada di bumi dan kapal yang berlayar di lautan dengan perintah-Nya. Dan Dia menahan (benda-benda) langit agar tidak jatuh ke bumi, melainkan dengan izin-Nya? Sungguh, Allah Maha Pengasih, Maha Penyayang kepada manusia.",
        shortTafsir: "Disamping mengajak Nabi untuk memperhatikan dan memikirkan proses turunnya hujan dari langit, Allah juga mengajak Nabi untuk memperhatikan kekuasaan-Nya yang lain dengan bertanya, \"Tidakkah engkau, Muhammad,\u00a0memperhatikan\u00a0dengan nalar dan kalbu\u00a0bahwa Allah menundukkan bagimu, manusia,\u00a0apa yang ada di\u00a0perut\u00a0bumi,\u00a0maupun yang di permukaannya, di darat maupun laut, berbagai jenis hewan, tumbuh-tumbuhan, dan berbagai jenis makhluk hidup bagi kepentingan kamu.\u00a0Dan\u00a0apakah kamu tidak memperhatikan\u00a0kapal yang berlayar di lautan, terapung meskipun membawa beban yang berat menempuh jarak ribuan mil\u00a0dengan\u00a0mematuhi\u00a0perintah-Nya, hukum alam ciptaan Allah?\u00a0Dan, apakah kamu tidak memperhatikan bahwa\u00a0Dia, Allah,\u00a0menahan\u00a0benda-benda\u00a0langit,\u00a0matahari, bulan, bintang, dan berbagai planet\u00a0agar tidak jatuh ke bumi,\u00a0yang akan menghancurkan kehidupan manusia,\u00a0kecuali dengan izin-Nya? Sungguh, Allah Maha Penyantun\u00a0kepada seluruh makhluk,\u00a0Maha Penyayang kepada manusia\u00a0yang beriman dengan memasukkan mereka ke dalam surga.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2660",
      ),
      Ayah(
        numberInSurah: 66,
        numberInQuran: 2661,
        juz: 17,
        page: 340,
        arab: "\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0625\u0650\u0646\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064e\u0641\u064f\u0648\u0631\u064c",
        transliteration: "Wa Huwal lazee ahyaakum summa yumeetukum summma yuheekum; innal insaana lakafoor",
        translation: "Dan Dialah yang menghidupkan kamu, kemudian mematikan kamu, kemudian menghidupkan kamu kembali (pada hari kebangkitan). Sungguh, manusia itu sangat kufur nikmat.",
        shortTafsir: "Allah tidak hanya menjadikan alam sebagai fasilitas bagi hidup dan kehidupan manusia dan menahan benda-benda langit agar tidak berjatuhan, tetapi juga menegaskan, \u201cDan Dia-lah yang menghidupkan kamu dengan meniupkan roh ke dalam dirimu, ketika kamu masih berupa janin, lalu kamu tumbuh dan berkembang; kemudian mematikan kamu dengan mencabut roh dari diri kamu, kemudian menghidupkan kamu kembali dalam kehidupan baru pada hari kebangkitan. Sungguh, manusia itu sangat kufur dan menutup diri dari nikmat Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2661",
      ),
      Ayah(
        numberInSurah: 67,
        numberInQuran: 2662,
        juz: 17,
        page: 340,
        arab: "\u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u064e\u0646\u0633\u064e\u0643\u064b\u0627 \u0647\u064f\u0645\u0652 \u0646\u064e\u0627\u0633\u0650\u0643\u064f\u0648\u0647\u064f \u06d6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u064e\u0627\u0632\u0650\u0639\u064f\u0646\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u06da \u0648\u064e\u0627\u062f\u0652\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u064b\u0649 \u0645\u0651\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d",
        transliteration: "Likulli ummatin ja'alnaa mansakan hum naasikoohu falaa yunaazi 'unnaka fil amr; wad'u ilaa Rabbika innaka la 'alaa hudam mustaqeem",
        translation: "Bagi setiap umat telah Kami tetapkan syariat tertentu yang (harus) mereka amalkan, maka tidak sepantasnya mereka berbantahan dengan engkau dalam urusan (syariat) ini dan serulah (mereka) kepada Tuhanmu. Sungguh, engkau (Muhammad) berada di jalan yang lurus.",
        shortTafsir: "Bagi setiap umat, seperti Yahudi dan Nasrani,\u00a0telah Kami tetapkan\u00a0melalui para utusan Allah\u00a0cara beribadah yang\u00a0harus\u00a0mereka amalkan\u00a0guna mendekatkan diri kepada-Nya.\u00a0Maka tidak sepantasnya mereka, kaum Yahudi dan Nasrani,\u00a0berbantahan dengan engkau,\u00a0Muhammad,\u00a0dalam urusan\u00a0cara beribadah kepada Allah ini;\u00a0dan serulah\u00a0kaum Yahudi dan Nasrani itu\u00a0kepada Tuhanmu\u00a0untuk beriman kepada Al-Qur\u2019an.\u00a0Sungguh, engkau\u00a0Muhammad,\u00a0berada di jalan yang lurus, baik dalam bidang akidah, ibadah (syariah), maupun akhlak.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2662",
      ),
      Ayah(
        numberInSurah: 68,
        numberInQuran: 2663,
        juz: 17,
        page: 340,
        arab: "\u0648\u064e\u0625\u0650\u0646 \u062c\u064e\u0627\u062f\u064e\u0644\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Wa in jaadalooka faqulil laahu a'lamu bimaa ta'maloon",
        translation: "Dan jika mereka membantah engkau, maka katakanlah, \u201cAllah lebih tahu tentang apa yang kamu kerjakan.\u201d",
        shortTafsir: "Dan jika mereka, kaum Yahudi dan Nasrani, membantah engkau, Muhammad, ketika engkau mengajarkan tauhid yang lurus, ibadah yang sempurna, dan akhlak yang mulia; maka katakanlah kepada ahli kitab, Yahudi dan Nasrani yang membantah kamu itu, \u201cAllah lebih tahu tentang apa yang kamu kerjakan,\u201d karena Allah benar-benar mengetahui yang tampak maupun yang tersembunyi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2663",
      ),
      Ayah(
        numberInSurah: 69,
        numberInQuran: 2664,
        juz: 17,
        page: 340,
        arab: "\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u0652\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",
        transliteration: "Allaahu yahkumu bainakum Yawmal Qiyaamati feemaa kuntum feehi takhtalifoon",
        translation: "Allah akan mengadili di antara kamu pada hari Kiamat tentang apa yang dahulu kamu memperselisihkannya.",
        shortTafsir: "Allah\u00a0tidak hanya mengetahui perbuatan kamu yang tampak maupun yang tersembunyi, tetapi juga\u00a0mengadili di antara kamu pada hari Kiamat\u00a0sehingga terungkap siapa yang salah dan siapa yang benar\u00a0tentang apa yang dahulu, seperti waktu kamu hidup bersama Rasulullah di Madinah,\u00a0kamu perselisihkan\u00a0tentang kebenaran Al-Qur\u2019an sebagai wahyu Allah dan kerasulan Nabi Muhammad.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2664",
      ),
      Ayah(
        numberInSurah: 70,
        numberInQuran: 2665,
        juz: 17,
        page: 340,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d \u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064c",
        transliteration: "Alam ta'lam annal laaha ya'lamu maa fis samaaa'i wal ard; inna zaalika fee kitaab; inna zaalika 'alal laahi yaseer",
        translation: "Tidakkah engkau tahu bahwa Allah mengetahui apa yang di langit dan di bumi? Sungguh, yang demikian itu sudah terdapat dalam sebuah Kitab (Lauh Mahfuzh). Sesungguhnya yang demikian itu sangat mudah bagi Allah.",
        shortTafsir: "Tidakkah engkau, Muhammad, tahu dengan ilmu yakin bahwa Allah mengetahui apa yang di langit, seperti malaikat dan benda-benda langit, dan seluruh makhluk Allah yang berada di bumi, baik yang kasat mata maupun tersembunyi bagi manusia? Sungguh, yang demikian itu bahwa Allah mengetahui secara detil dan terperinci semua ciptaan-Nya di langit maupun di bumi, sudah terdapat dalam sebuah Kitab induk yang tersimpan di Lauh Mahfuzh Sesungguhnya yang demikian itu, tercatatnya data seluruh ciptaan Allah pada sebuah buku induk, sangat mudah bagi Allah, karena Allah Tuhan Yang Memelihara seluruh alam.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2665",
      ),
      Ayah(
        numberInSurah: 71,
        numberInQuran: 2666,
        juz: 17,
        page: 340,
        arab: "\u0648\u064e\u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u0652 \u0628\u0650\u0647\u0650 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064c \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064d",
        transliteration: "Wa ya'budoona min doonil laahi maa lam yunazzil bihee sultaananw wa maa laisa lahum bihee 'ilm; wa maa lizzaalimeena min naseer",
        translation: "Dan mereka menyembah selain Allah, tanpa dasar yang jelas tentang itu, dan mereka tidak mempunyai pengetahuan (pula) tentang itu. Bagi orang-orang yang zalim tidak ada seorang penolong pun.",
        shortTafsir: "Dan mereka, orang-orang kafir itu,\u00a0menyembah\u00a0tuhan\u00a0selain Allah\u00a0dengan bangga, tanpa merasa bersalah,\u00a0tanpa dasar yang jelas tentang itu, baik yang bersumber dari akal sehat, nurani, apa lagi dari wahyu;\u00a0dan mereka\u00a0pun\u00a0tidak mempunyai pengetahuan\u00a0yang menjadi dasar penyembahan tuhan selain Allah itu. Allah menegaskan bahwa\u00a0bagi orang-orang yang zalim,\u00a0yakni orang-orang yang menyembah tuhan selain Allah, akan kekal di dalam neraka.\u00a0Tidak ada seorang penolong pun\u00a0yang dapat menyelamatkan mereka dari azab yang pedih itu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2666",
      ),
      Ayah(
        numberInSurah: 72,
        numberInQuran: 2667,
        juz: 17,
        page: 340,
        arab: "\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u062a\u064e\u0639\u0652\u0631\u0650\u0641\u064f \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0652\u0645\u064f\u0646\u0643\u064e\u0631\u064e \u06d6 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0633\u0652\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06d7 \u0642\u064f\u0644\u0652 \u0623\u064e\u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0634\u064e\u0631\u0651\u064d \u0645\u0651\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u06d7 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0639\u064e\u062f\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u06d6 \u0648\u064e\u0628\u0650\u0626\u0652\u0633\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0631\u064f",
        transliteration: "Wa izaa tutlaa 'laihim Aayaatunaa baiyinaatin ta'rifu fee wujoohil lazeena kafarul munkara yakaadoona yastoona bil lazeena yatloona 'alaihim Aayaatinaa; qul afa unab bi'ukum bisharrim min zaalikum; an Naaru wa 'adahal laahul lazeena kafaroo wa bi'sal maseer",
        translation: "Dan apabila dibacakan di hadapan mereka ayat-ayat Kami yang terang, niscaya engkau akan melihat (tanda-tanda) keingkaran pada wajah orang-orang yang kafir itu. Hampir-hampir mereka menyerang orang-orang yang membacakan ayat-ayat Kami kepada mereka. Katakanlah (Muhammad), \u201cApakah akan aku kabarkan kepada-mu (mengenai sesuatu) yang lebih buruk dari itu, (yaitu) neraka?\u201d Allah telah mengancamkannya (neraka) kepada orang-orang kafir. Dan (neraka itu) seburuk-buruk tempat kembali.",
        shortTafsir: "Orang-orang kafir tidak hanya menyembah tuhan selain Allah, tetapi juga\u00a0apabila dibacakan di hadapan mereka, oleh Nabi atau para sahabat,\u00a0ayat-ayat Kami\u00a0yang berisi ajaran tauhid, ibadah, dan akhlak\u00a0yang terang, karena rasional atau masuk akal,\u00a0niscaya engkau akan melihat\u00a0tanda-tanda\u00a0keingkaran pada wajah orang-orang yang kafir itu\u00a0terhadap ajaran tauhid, ibadah, dan akhlak. Kemarahan mereka kepada orang yang membacakan ayat itu demikian dahsyat.\u00a0Hampir-hampir mereka menyerang\u00a0para mubalig, orang-orang\u00a0yang membacakan ayat-ayat Kami kepada mereka\u00a0sehingga mengancam keselamatan mereka.\u00a0Katakanlah,\u00a0wahai Muhammad kepada orang-orang kafir itu, \u201cApakah\u00a0kamu bersedia mendengarkan,\u00a0akan aku kabarkan kepada kamu\u00a0sesuatu yang lebih buruk dari itu, yaitu\u00a0neraka?\u201d Allah telah menjadikan neraka\u00a0ancaman\u00a0yang membahayakan\u00a0kepada orang-orang kafir. Dan\u00a0neraka itu\u00a0seburuk-buruk tempat kembali\u00a0di akhirat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2667",
      ),
      Ayah(
        numberInSurah: 73,
        numberInQuran: 2668,
        juz: 17,
        page: 341,
        arab: "\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0636\u064f\u0631\u0650\u0628\u064e \u0645\u064e\u062b\u064e\u0644\u064c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0646 \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f\u0648\u0627 \u0630\u064f\u0628\u064e\u0627\u0628\u064b\u0627 \u0648\u064e\u0644\u064e\u0648\u0650 \u0627\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0633\u0652\u0644\u064f\u0628\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0630\u0651\u064f\u0628\u064e\u0627\u0628\u064f \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0646\u0642\u0650\u0630\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u06da \u0636\u064e\u0639\u064f\u0641\u064e \u0627\u0644\u0637\u0651\u064e\u0627\u0644\u0650\u0628\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0637\u0652\u0644\u064f\u0648\u0628\u064f",
        transliteration: "Yaaa ayyuhan naasu duriba masalun fastami'oo lah; innal lazeena tad'oona min doonil laahi lai yakhluqoo zubaabanw wa lawijtama'oo lahoo wa iny yaslub humuz zubbabu shai'al laa yastan qizoohu minh; da'ufat taalibu walmatloob",
        translation: "Wahai manusia! Telah dibuat suatu perumpamaan. Maka dengarkanlah! Sesungguhnya segala yang kamu seru selain Allah tidak dapat menciptakan seekor lalat pun, walaupun mereka bersatu untuk menciptakannya. Dan jika lalat itu merampas sesuatu dari mereka, mereka tidak akan dapat merebutnya kembali dari lalat itu. Sama lemahnya yang menyembah dan yang disembah.",
        shortTafsir: "Allah menjelaskan bagaimana kualitas tuhan-tuhan selain Allah yang disembah oleh orang-orang kafir. Wahai manusia! Perhatikanlah dengan cermat, telah dibuat suatu perumpamaan yang harus dijadikan renungan oleh kamu. Maka dengarkanlah dengan saksama! Sesungguhnya semua tuhan selain Allah yang kamu seru dalam ritual kamu tidak dapat menciptakan seekor lalat pun, yang menunjukkan ketidakpantasan tuhan-tuhan selain Allah itu dijadikan tuhan, walaupun mereka bersatu dalam sebuah tim untuk menciptakannya. Dan jika lalat itu merampas sesuatu dari mereka, mereka tuhan-tuhan selain Allah itu tidak akan dapat merebutnya kembali dari lalat itu, karena patung-patung yang disembah itu benda mati. Sama lemahnya yang menyembah dan yang disembah, karena keduanya sama-sama makhluk Allah yang tidak mampu menciptakan apapun baik makhluk hidup maupun benda mati.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2668",
      ),
      Ayah(
        numberInSurah: 74,
        numberInQuran: 2669,
        juz: 17,
        page: 341,
        arab: "\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u0652\u0631\u0650\u0647\u0650 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",
        transliteration: "Maa qadrul laaha haqqa qadrih; innal laaha la Qawiyyun 'Azeez",
        translation: "Mereka tidak mengagungkan Allah dengan sebenar-benarnya. Sungguh, Allah Mahakuat, Mahaperkasa.",
        shortTafsir: "Manusia yang menyembah tuhan selain Allah sejatinya\u00a0mereka tidak mengagungkan Allah dengan sebenar-benarnya,\u00a0bahkan merendahkan-Nya dengan tidak mengibadati-Nya.\u00a0Sesungguhnya Allah\u00a0benar-benar\u00a0Mahakuat\u00a0meskipun tidak dijadikan tuhan oleh mereka dan\u00a0Mahaperkasa\u00a0untuk mengalahkan tuhan-tuhan selain Dia.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2669",
      ),
      Ayah(
        numberInSurah: 75,
        numberInQuran: 2670,
        juz: 17,
        page: 341,
        arab: "\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0635\u0652\u0637\u064e\u0641\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0628\u064e\u0635\u0650\u064a\u0631\u064c",
        transliteration: "Allahu yastafee minal malaaa'ikati Rusulanw wa minan naas; innal laaha Samee'um Baseer",
        translation: "Allah memilih para utusan(-Nya) dari malaikat dan dari manusia. Sesungguhnya Allah Maha Mendengar, Maha Melihat.",
        shortTafsir: "Allah memilih para utusan-Nya dari malaikat untuk menyampaikan wahyu kepada para nabi dan rasul, dan juga memilih dari manusia, sejak Nabi Adam hingga Nabi Muhammad, karena kasih sayang-Nya kepada manusia untuk menjelaskan kepada mereka bahwa sesungguhnya tidak ada tuhan selain Allah dan tidak layak beribadah kecuali kepada-Nya. Sesungguhnya Allah Maha Mendengar semua pembi-caraan makhluk, baik yang terucap maupun yang tersimpan dalam hati; Maha Melihat seluruh ciptaan-Nya, baik yang di langit maupun di perut bumi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2670",
      ),
      Ayah(
        numberInSurah: 76,
        numberInQuran: 2671,
        juz: 17,
        page: 341,
        arab: "\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u064f",
        transliteration: "Ya'lamu maa baina aydeehim wa maa khalfahum; wa ilal laahi turja'ul umoor",
        translation: "Dia (Allah) mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka. Dan hanya kepada Allah dikembalikan segala urusan.",
        shortTafsir: "Allah tidak hanya Maha Mendengar dan Maha Melihat, tetapi\u00a0Dia\u00a0juga\u00a0mengetahui apa yang di hadapan mereka, yang belum terjadi, karena pengetahuan Allah tidak terikat oleh ruang dan waktu,\u00a0dan\u00a0mengetahui pula\u00a0apa yang di belakang mereka, yang sudah terjadi di masa silam. Oleh karena itu, manusia harus meyakini dengan penuh keinsafan\u00a0bahwa hanya kepada Allah dikembalikan segala urusan, karena sesungguhnya Allah yang mengurus seluruh alam dan seluruh manusia akan kembali menghadap Allah di akhirat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2671",
      ),
      Ayah(
        numberInSurah: 77,
        numberInQuran: 2672,
        juz: 17,
        page: 341,
        arab: "\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u0631\u0652\u0643\u064e\u0639\u064f\u0648\u0627 \u0648\u064e\u0627\u0633\u0652\u062c\u064f\u062f\u064f\u0648\u0627 \u0648\u064e\u0627\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064f\u0641\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e \u06e9",
        transliteration: "Yaaa ayyuhal lazeena aamanur ka'oo wasjudoo wa'budoo Rabbakum waf'alul khaira la'allakum tuflihoon",
        translation: "Wahai orang-orang yang beriman! Rukuklah, sujudlah, dan sembahlah Tuhanmu; dan berbuatlah kebaikan, agar kamu beruntung.",
        shortTafsir: "Orang beriman diperintahkan untuk beribadah kepada Allah Yang Maha Mengetahui keadaan manusia. Wahai orang-orang yang beriman, karena kamu sudah membenarkan dan meyakini bahwa sesungguhnya tidak ada tuhan selain Allah, maka rukuklah, sujudlah, dan beribadahlah kepada Tuhanmu dengan melaksanakan salat wajib dan berbagai salat sunah, dan sebagai dampak ketekunan beribadah tersebut, maka berbuatlah kebaikan kepada sesama manusia agar kamu beruntung dalam kehidupan pribadi, keluarga dan masyarakat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2672",
      ),
      Ayah(
        numberInSurah: 78,
        numberInQuran: 2673,
        juz: 17,
        page: 341,
        arab: "\u0648\u064e\u062c\u064e\u0627\u0647\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064e \u062c\u0650\u0647\u064e\u0627\u062f\u0650\u0647\u0650 \u06da \u0647\u064f\u0648\u064e \u0627\u062c\u0652\u062a\u064e\u0628\u064e\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u0650\u0646\u0652 \u062d\u064e\u0631\u064e\u062c\u064d \u06da \u0645\u0651\u0650\u0644\u0651\u064e\u0629\u064e \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u0652 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u06da \u0647\u064f\u0648\u064e \u0633\u064e\u0645\u0651\u064e\u0627\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u064f \u0648\u064e\u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u06da \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064e \u0648\u064e\u0622\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u0651\u064e\u0643\u064e\u0627\u0629\u064e \u0648\u064e\u0627\u0639\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u0652\u0644\u064e\u0627\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0644\u064e\u0649\u0670 \u0648\u064e\u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064f",
        transliteration: "Wa jaahidoo fil laahi haqqa jihaadih; Huwaj tabaakum wa maa ja'ala 'alaikum fid deeni min haraj; Millata abeekum Ibraaheem; Huwa sammaakumul muslimeena min qablu wa fee haaza li yakoonar Rasoolu shaheedan 'alaikum wa takoonoo shuhadaaa'a 'alan naas; fa aqeemus salaata wa aatuz zakaata wa'tasimoo billaahi Huwa mawlaakum fani'mal mawlaa wa ni'man naseer",
        translation: "Dan berjihadlah kamu di jalan Allah dengan jihad yang sebenar-benarnya. Dia telah memilih kamu, dan Dia tidak menjadikan kesukaran untukmu dalam agama. (Ikutilah) agama nenek moyangmu Ibrahim. Dia (Allah) telah menamakan kamu orang-orang muslim sejak dahulu, dan (begitu pula) dalam (Al-Qur'an) ini, agar Rasul (Muhammad) itu menjadi saksi atas dirimu dan agar kamu semua menjadi saksi atas segenap manusia. Maka laksanakanlah salat; tunaikanlah zakat, dan berpegangteguhlah kepada Allah. Dialah Pelindungmu; Dia sebaik-baik pelindung dan sebaik-baik penolong.",
        shortTafsir: "Setelah dijelaskan pada ayat di atas bahwa untuk meraih keberuntungan, orang beriman diperintahkan untuk beribadah kepada Allah dan berbuat baik kepada sesama manusia, pada ayat ini dijelaskan bahwa untuk meraih keberuntungan, orang beriman diperintahkan untuk berjihad pada jalan Allah. Untuk meraih keberuntungan itu, beribadahlah kamu, wahai orang-orang yang beriman,\u00a0dan berjihadlah kamu di jalan Allah, yakni mencurahkan seluruh potensi dan kemampuan untuk mengharumkan Islam dan kaum muslim\u00a0dengan jihad yang sebenar-benarnya, perjuangan yang total dalam menggali seluruh potensi dan kemampuan.\u00a0Dia telah memilih kamu, wahai Muhammad untuk menjadi nabi dan rasul pamungkas;\u00a0dan Dia, Allah,\u00a0tidak menjadikan kesukaran untukmu dalam agama,\u00a0yakni dalam melaksanakan ajaran Islam ini, karena Islam menekankan prinsip memudahkan, meminimalkan beban, dan bertahap dalam menetapkan syariah, hukum agama. Memeluk Islam dan menjadi muslim itu merupakan kelanjutan dari\u00a0agama nenek moyangmu Ibrahim, yakni meyakini tidak ada tuhan selain Allah dan tidak beribadah kecuali kepada-Nya.\u00a0Dia\u00a0(Allah)\u00a0telah menamakan kamu, orang-orang yang meyakini prinsip tauhid itu, adalah\u00a0orang-orang muslim, berserah diri kepada Allah,\u00a0sejak dahulu, dan\u00a0begitu pula kamu dinamakan muslim\u00a0dalam\u00a0Al-Qur\u2019an\u00a0ini, agar Rasul, Nabi Muhammad\u00a0itu menjadi saksi atas diri kamu semua\u00a0dalam mengamalkan ajaran Islam\u00a0dan agar kamu semua menjadi saksi atas segenap manusia\u00a0dalam mewujudkan prinsip tidak ada tuhan selain Allah dan tidak beribadah kecuali kepada-Nya.\u00a0Maka, sejalan dengan prinsip tersebut,\u00a0laksanakanlah salat\u00a0dengan baik dan benar sesuai syarat dan rukunnya, serta tepat waktu;\u00a0tunaikanlah zakat\u00a0dengan sempurna,\u00a0dan berpegangteguhlah kepada Allah\u00a0dalam pikiran dan perasaan.\u00a0Dialah Pelindungmu\u00a0dari segala bencana dunia-akhirat;\u00a0Dia sebaik-baik pelindung dan sebaik-baik penolong\u00a0bagi manusia dan seluruh makhluk.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2673",
      ),
    ],
  );
}
